/* Prototipo autónomo: todas las integraciones del dispositivo se simulan. */
(() => {
  'use strict';
  const M=window.Cabal, $=selector=>document.querySelector(selector), esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',list:'M6 3h12v18H6zM9 7h6M9 11h6M9 15h4',wallet:'M4 6h15v14H4zM4 6V4h13v2M15 11h6v5h-6z',chart:'M4 20V4M4 20h17M8 17v-5M13 17V7M18 17v-8',more:'M5 12h.01M12 12h.01M19 12h.01',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',plus:'M12 5v14M5 12h14',minus:'M5 12h14',transfer:'M4 8h15l-4-4M20 16H5l4 4',inbox:'M4 4h16v16H4zM4 14h5l2 3h2l2-3h5',card:'M3 5h18v14H3zM3 10h18M6 15h3',bank:'m3 8 9-5 9 5M4 9h16M6 10v8M12 10v8M18 10v8M3 21h18M4 18h16',cash:'M3 6h18v12H3zM12 9a3 3 0 1 0 .01 0M6 9v6M18 9v6',saving:'M5 8h12l3 4v6h-3v3h-3v-3H9v3H6v-3H3v-7h2zM9 5h5M16 11h.01',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h3',search:'M10 4a6 6 0 1 0 0 12 6 6 0 0 0 0-12M15 15l5 5',filter:'M4 6h16M7 12h10M10 18h4',settings:'M12 8a4 4 0 1 0 .01 0M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',template:'M6 3h12v18l-6-4-6 4z',lock:'M6 10h12v11H6zM8 10V7a4 4 0 0 1 8 0v3',shield:'M12 3 21 7v6c0 4-9 8-9 8s-9-4-9-8V7zM8 12l3 3 5-6',file:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6',store:'M3 9l2-5h14l2 5M4 9v12h16V9M9 21v-7h6v7M3 9h18',check:'m5 12 4 4 10-10',close:'m6 6 12 12M18 6 6 18',info:'M12 3a9 9 0 1 0 .01 0M12 11v6M12 7h.01',edit:'m4 16 12-12 4 4-12 12H4z',refresh:'M20 8V3l-4 4M20 8a8 8 0 1 0 1 7',test:'M9 3h6M10 3v6l-6 10c-1 2 1 2 2 2h12c1 0 3 0 2-2L14 9V3M8 14h8'};
  const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
  const button=(text,action,id='',cls='secondary',extra='')=>`<button type="button" class="button ${cls}" data-action="${action}" data-id="${esc(id)}" ${extra}>${text}</button>`;
  const typeLabels={expense:'Gasto',income:'Ingreso',transfer:'Transferencia',payment:'Pago de tarjeta',refund:'Devolución',adjustment:'Ajuste'};
  const accountLabels={bank:'Cuenta bancaria',cash:'Efectivo',saving:'Ahorro',credit:'Tarjeta de crédito'};
  const aName=id=>M.account(data,id)?.name||'Sin cuenta';
  const cName=id=>data.categories.find(c=>c.id===id)?.name||'Sin categoría';
  const dateLabel=date=>new Date(date+'T12:00:00').toLocaleDateString('es-PY',{day:'numeric',month:'short',year:'numeric'});
  const monthLabel=date=>new Date(date+'-01T12:00:00').toLocaleDateString('es-PY',{month:'long',year:'numeric'});
  const monthEnd=date=>M.addMonths(date+'-01',1).slice(0,7)+'-01';
  const lastDay=date=>{const d=new Date(monthEnd(date)+'T12:00:00');d.setDate(d.getDate()-1);return d.toISOString().slice(0,10);};
  const pending=()=>data.pending.filter(p=>!p.ignored&&!p.confirmed);
  const activeAccounts=()=>data.accounts.filter(a=>!a.archived);
  let savedBackup=null,previousRestore=null,receivingStorage=false;
  let data,view={page:'home'},stack=[],modal=null,modalPayload=null,modalBaseline='',lastFocus=null,undoAction=null,toastTimer,locked=false,onboardingStep=0;
  let ui={history:{search:'',account:'',merchant:'',category:'',type:'',start:'',end:'',limit:50},analysis:'budgets',budgetMonth:'2026-10',month:'2026-10',reportView:'Resumen',reportAccount:'',reportCategory:'',reportStart:'',reportEnd:'',accountType:'',archived:false,catalog:'merchants'};
  function persist(){if(receivingStorage)return;try{localStorage.setItem('cabal-prototype-v1',JSON.stringify(data));}catch{} }
  function readLatest(){try{const saved=JSON.parse(localStorage.getItem('cabal-prototype-v1'));if(saved?.transactions&&saved?.categories)data=saved;}catch{}}
  function load(){try{const saved=JSON.parse(localStorage.getItem('cabal-prototype-v1'));data=saved&&saved.transactions&&saved.categories?saved:M.seed();}catch{data=M.seed();}$('#scenario').value=data.scenario;if(!data.onboarding)view={page:'onboarding'};}
  function reset(scenario){data=M.seed(scenario);M.processSchedules(data);$('#scenario').value=scenario;savedBackup=null;previousRestore=null;stack=[];modal=null;locked=false;onboardingStep=0;ui.history={search:'',account:'',merchant:'',category:'',type:'',start:'',end:'',limit:50};ui.month='2026-10';ui.budgetMonth='2026-10';ui.reportStart='';ui.reportEnd='';view={page:scenario==='first'?'onboarding':scenario==='wallet'?'inbox':scenario==='scheduled'?'scheduled':scenario==='analysis'?'analysis':scenario==='files'?'backup':scenario==='developer'?'developer':'home'};persist();render();}
  function notify(message,undo=null){clearTimeout(toastTimer);undoAction=undo;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button data-action="undo">Deshacer</button>':''}`;$('#toast').className='show';toastTimer=setTimeout(()=>{$('#toast').className='';undoAction=null;},undo?12000:5500);}
  function go(page,params={},root=false){if(root){stack=[];}else{stack.push({view:M.clone(view),scroll:$('.content')?.scrollTop||0});}view={page,...params};render();if($('.content'))$('.content').scrollTop=0;focusHeading();}
  function back(){const previous=stack.pop();view=previous?.view||{page:'home'};render();if(previous&&$('.content'))$('.content').scrollTop=previous.scroll;focusHeading();}
  function focusHeading(){const heading=$('.app-header h2')||$('.more-content');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
  function header(title,subtitle='',right=''){return `<header class="app-header">${stack.length?`<button class="icon-button" data-action="back" aria-label="Volver">${icon('back')}</button>`:''}<div class="header-title"><h2>${title}</h2></div>${right}</header>`;}
  function nav(){const selected=['home','history','accounts','analysis','more'].includes(view.page)?view.page:['account','accountDetail'].includes(view.page)?'accounts':view.page==='inbox'?'home':['detail','paymentDetail','payments','templates','scheduled'].includes(view.page)?(stack.slice().reverse().find(s=>['home','history','accounts','analysis','more'].includes(s.view.page))?.view.page||'more'):'more';return `<nav class="nav" aria-label="Navegación principal">${[['home','Inicio','home'],['history','Movimientos','list'],['accounts','Cuentas','wallet'],['analysis','Análisis','chart'],['more','Más','more']].map(([id,label,i])=>`<button data-action="nav" data-id="${id}" class="${selected===id?'active':''}" ${selected===id?'aria-current="page"':''}><span class="nav-icon">${icon(i)}</span>${label}${id==='home'&&pending().length?'<span class="dot"></span>':''}</button>`).join('')}</nav>`;}
  function render(){persist();if(locked){$('#app').innerHTML=header('Cabal')+`<div class="locked"><span class="round-icon">${icon('lock')}</span><h2>Cabal bloqueado</h2>${button('Desbloquear','unlock','','primary')}</div>`;}else {const screens={home,payments,paymentDetail,history,accounts,accountDetail,account:accountDetail,analysis,more,inbox,templates,scheduled:templates,wallet,catalog,backup,security,info,developer,diagnostic,inspector,onboarding,detail};$('#app').innerHTML=(screens[view.page]||home)()+(view.page==='home'?homeActions():'')+(view.page==='history'?`<div class="history-create">${button(icon('plus')+' Nuevo','new','expense','primary')}</div>`:'')+(!['onboarding','detail'].includes(view.page)?nav():'');}document.querySelectorAll('.tabs button,.scroll-tabs button').forEach(el=>el.setAttribute('aria-pressed',String(el.classList.contains('active'))));renderModal();}
  function empty(title,text,cta=''){return `<div class="empty">${icon('wallet')}<h3>${title}</h3>${cta}</div>`;}
  function transactionRow(t){const name=t.merchant||typeLabels[t.type];const sign=t.type==='expense'?'−':t.type==='income'||t.type==='refund'?'+':'';return `<button class="row" data-action="${t.installmentIndex?'installment-detail':'detail'}" data-id="${esc(t.id)}" ${t.installmentIndex?`data-index="${t.installmentIndex}"`:""}><span class="round-icon">${icon(t.type==='expense'?'minus':t.type==='income'||t.type==='refund'?'plus':'transfer')}</span><span class="grow"><strong>${esc(name)}</strong><small>${esc(aName(t.from||t.to))} · ${dateLabel(t.date)}${t.installmentIndex?` · Cuota ${t.installmentIndex}/${t.quotas}${t.planned?' · Prevista':''}`:''}${t.source!=='Manual'?` · ${esc(t.source)}`:''}</small></span><span class="money ${t.type==='income'||t.type==='refund'?'income':'expense'}">${sign}${M.money(t.amount)}</span></button>`;}
  const obligations=()=>data.obligations||[];
  const remaining=o=>M.obligationRemaining(data,o);
  function paymentState(o){return o.cancelled?'Cancelado':remaining(o)===0?(o.carryOut?'Saldo trasladado':'Pagado'):o.due<M.TODAY?'Vencido':'Pendiente';}
  function paymentRow(o){return `<button class="row payment-row" data-action="payment-detail" data-id="${esc(o.id)}"><span class="round-icon">${icon('calendar')}</span><span class="grow"><strong>${esc(o.name)}</strong><small>${dateLabel(o.due)}${o.planId?' · Cuota '+o.index+'/'+o.count:(o.frequency==='yearly'?' · Anual':' · Mensual')}${o.carryIn?' · Incluye saldo anterior':''}</small><span class="chip ${remaining(o)?'warn':''}">${paymentState(o)}</span></span><span class="money">${M.money(remaining(o)||M.obligationPayments(data,o.id).reduce((sum,t)=>sum+t.amount,0))}</span>${icon('arrow')}</button>`;}
  function home(){
    const open=obligations().filter(o=>remaining(o)>0).sort((a,b)=>a.due.localeCompare(b.due));
    const month=M.month(M.TODAY),thisMonth=M.pendingAmount(data,month+'-01',lastDay(month));
    return header('Cabal','',`<button class="icon-button" data-action="go" data-id="inbox" aria-label="Compras por revisar">${icon('inbox')}${pending().length?`<span class="badge">${pending().length}</span>`:''}</button>`)+`<section class="content home-content"><div class="hero"><span class="balance-label">Dinero disponible</span><div class="amount">${M.money(M.availableMoney(data)).replace(' ₲',' <small>₲</small>')}</div></div><div class="financial-summary"><button data-action="go" data-id="payments"><span>Pendiente este mes</span><strong>${M.money(thisMonth)}</strong><small>Ver vencimientos ${icon('arrow')}</small></button><button data-action="worth-info"><span>Patrimonio financiero</span><strong>${M.money(M.netWorth(data))}</strong></button></div>${open.length?`<div class="section-head"><h3>Próximos pagos</h3><button class="text-button" data-action="go" data-id="payments">Ver todos</button></div>${open.slice(0,2).map(paymentRow).join('')}`:`<button class="notice" data-action="go" data-id="payments">${icon('calendar')}<span class="grow">Organizá tus próximos pagos</span>${icon('arrow')}</button>`}<div class="section-head"><h3>Tus cuentas</h3><button class="text-button" data-action="nav" data-id="accounts">Ver todas</button></div><div class="account-list">${activeAccounts().map(accountCard).join('')}</div>${!activeAccounts().length?empty('Sin cuentas','Agregá una cuenta para empezar.',button('Agregar cuenta','account-new')):''}<div class="section-head"><h3>Últimos movimientos</h3><button class="text-button" data-action="nav" data-id="history">Ver todos</button></div>${M.movementRows(data).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(transactionRow).join('')}</section>`;
  }
  function payments(){
    const filter=ui.paymentFilter||'pending';const rows=obligations().filter(o=>filter==='paid'?M.obligationPayments(data,o.id).length>0:filter==='all'?true:remaining(o)>0).sort((a,b)=>a.due.localeCompare(b.due));
    let group='';
    return header('Pagos pendientes','',button(icon('plus'),'plan-new','','secondary','aria-label="Nueva compra en cuotas"'))+`<section class="content"><div class="payment-total"><span>Por pagar este mes</span><strong>${M.money(M.pendingAmount(data,M.month(M.TODAY)+'-01',lastDay(M.month(M.TODAY))))}</strong></div><div class="tabs">${[['pending','Pendientes'],['paid','Con pagos'],['all','Todos']].map(([id,label])=>button(label,'payment-filter',id,filter===id?'active':'secondary')).join('')}</div>${rows.map(o=>{const month=M.month(o.due),heading=month!==group?`<h3 class="due-month">${monthLabel(month)}</h3>`:'';group=month;return heading+paymentRow(o);}).join('')||empty('Sin pagos en esta vista','Podés crear una compra en cuotas o programar una plantilla.')}<div class="actions">${button('Compra en cuotas','plan-new')}${button('Plantillas','go','templates')}</div></section>`;
  }
  function paymentDetail(){
    const o=obligations().find(o=>o.id===view.id);if(!o)return header('Pago')+empty('Pendiente no disponible','Volvé a la lista de pagos.');
    const paid=M.obligationPayments(data,o.id),r=o.reminder||M.defaultReminder();
    const group=o.planId?obligations().filter(n=>n.planId===o.planId).sort((a,b)=>a.index-b.index):[];
    return header(o.planId?'Cuota '+o.index+' de '+o.count:'Gasto mensual')+`<section class="content"><h3 class="payment-name">${esc(o.name)}</h3><span class="chip ${remaining(o)?'warn':''}">${paymentState(o)}</span><div class="payment-total"><span>Por pagar</span><strong>${M.money(remaining(o))}</strong></div>${dataLine('Vencimiento',dateLabel(o.due))}${dataLine('Cuenta propuesta',esc(aName(o.from)))}${dataLine('Importe previsto',M.money(o.amount))}${o.carryIn?dataLine('Saldo anterior',M.money(o.carryIn)):''}${(o.carriedFrom||[]).map(c=>`<p class="helper">${M.money(c.amount)} del vencimiento ${dateLabel(c.due)}. </p>`).join('')}${o.carryOut?dataLine('Trasladado al siguiente pago',M.money(o.carryOut)):''}${remaining(o)>0?button('Confirmar pago','payment-confirm',o.id,'primary full'):''}<div class="section-head"><h3>Recordatorio</h3><button class="text-button" data-action="reminder-edit" data-id="${esc(o.id)}">Editar</button></div><p class="muted">${r.enabled?`${r.days} días antes${r.onDue?' y el día del vencimiento':''} · ${esc(r.time)}`:'Desactivado'}</p>${r.enabled&&remaining(o)>0?button('Ver aviso de ejemplo','reminder-preview',o.id,'secondary full'):''}${paid.length?`<div class="section-head"><h3>Pagos confirmados</h3></div>${paid.map(t=>`<div class="row"><span class="grow"><strong>${M.money(t.amount)}</strong><small>${dateLabel(t.date)} · ${esc(aName(t.from))}</small></span><span class="chip">Confirmado</span></div>`).join('')}`:''}${group.length?`<details class="inline"><summary>Plan completo · ${M.money(group.reduce((sum,n)=>sum+n.amount,0))}</summary>${group.map(paymentRow).join('')}</details>`:''}${remaining(o)>0?`<div class="actions">${button('Editar pendiente','obligation-edit',o.id)}${button('Cancelar pendiente','obligation-cancel',o.id,'danger')}</div>`:''}</section>`;
  }
  function reminderFields(r=M.defaultReminder()){return checkbox('Activar recordatorios','reminderEnabled',r.enabled)+field('Días antes del vencimiento','reminderDays',r.days,'number','min="0" max="60"')+field('Hora del aviso','reminderTime',r.time,'time')+checkbox('Avisar también el día del vencimiento','reminderOnDue',r.onDue);}
  function readReminder(v){const days=Number(v.get('reminderDays')),time=String(v.get('reminderTime')||'');if(!Number.isInteger(days)||days<0||days>60||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))throw Error('Elegí entre 0 y 60 días y una hora válida.');return {enabled:v.has('reminderEnabled'),days,time,onDue:v.has('reminderOnDue')};}
  function planForm(){openModal('Compra en cuotas',form('plan',`${field('¿Qué compraste?','name','')}${field('Importe total PYG','amount','','text','inputmode="numeric"')}${field('Cantidad de cuotas','count',10,'number','min="1" max="120"')}${field('Primera cuota','first',M.TODAY,'date')}${selectField('Cuenta propuesta para pagar','from',activeAccounts().filter(a=>a.type!=='credit').map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join(''))}${selectField('Categoría','category',categoryOptions('','expense',false))}<details class="inline"><summary>Recordatorios</summary>${reminderFields()}</details>`,'Crear plan pendiente'));}
  function confirmPayment(id){const o=obligations().find(o=>o.id===id);if(!o||!remaining(o))throw Error('Este pago ya está resuelto.');const next=obligations().filter(n=>(o.planId?n.planId===o.planId:n.templateId===o.templateId)&&n.due>o.due&&remaining(n)>0).sort((a,b)=>a.due.localeCompare(b.due))[0];openModal('Confirmar pago',form('obligation-payment',`<p class="muted">${esc(o.name)} · Vence ${dateLabel(o.due)}</p>${dataLine('Saldo pendiente',M.money(remaining(o)))}${field('Importe que pagaste PYG','amount',remaining(o),'text','inputmode="numeric"')}${field('Fecha del pago','date',M.TODAY,'date',`max="${M.TODAY}"`)}${selectField('¿Con qué cuenta pagaste?','from',activeAccounts().filter(a=>!o.planId||a.type!=='credit').map(a=>`<option value="${esc(a.id)}" ${a.id===o.from?'selected':''}>${esc(a.name)}</option>`).join(''))}${o.templateId&&!o.carryIn&&!o.carryOut&&!M.obligationPayments(data,o.id).length?checkbox('Este es el importe final de la factura','finalAmount',true):''}${next||o.templateId?checkbox('Si es un pago parcial, sumar el resto al próximo vencimiento','carry',true):''}`,'Registrar pago'),{id,expectedRemaining:remaining(o)});}
  function homeActions(){return `<div class="home-fab"><button class="fab-button" data-action="movement-actions" aria-label="Nuevo movimiento" aria-haspopup="dialog">${icon('plus')}</button></div>`;}
  function movementActions(){openModal('Nuevo movimiento',`<div class="movement-actions">${[['expense','Gasto','minus'],['income','Ingreso','plus'],['transfer','Transferir','transfer'],['plan','Compra en cuotas','calendar']].map(([id,label,i])=>button(icon(i)+'<span>'+label+'</span>',id==='plan'?'plan-new':'new',id,'action-row')).join('')}</div>`,{presentation:'sheet'});}

  function accountCard(a){return `<button class="account-card ${a.type==='credit'?'credit':''}" data-action="account-actions" data-id="${a.id}"><span class="account-top">${icon(a.type==='credit'?'card':a.type)}${icon('arrow')}</span><h4>${esc(a.name)}</h4><div class="value">${M.money(M.balance(data,a.id))}</div><small>${a.type==='credit'?'Deuda registrada':a.type==='saving'?'Ahorro · '+(a.available?'incluido en disponible':'fuera de disponible'):'Saldo registrado'}${a.archived?' · Archivada':''}</small></button>`;}
  function historyRows(){const f=ui.history;return M.movementRows(data,f.end||M.TODAY).filter(t=>{const search=(t.merchant+' '+t.note).toLowerCase();if(f.search&&!search.includes(f.search.toLowerCase()))return false;if(f.account&&t.from!==f.account&&t.to!==f.account)return false;if(f.merchant&&t.merchant!==f.merchant)return false;if(f.category&&!M.parts(t).some(p=>p.category===f.category))return false;if(f.type&&t.type!==f.type)return false;if(f.unclassified&&!M.parts(t).some(p=>!p.category))return false;if(f.withoutMerchant&&t.merchant)return false;if(f.report&&!['expense','refund','income'].includes(t.type))return false;return (!f.start||t.date>=f.start)&&(!f.end||t.date<=f.end);}).sort((a,b)=>b.date.localeCompare(a.date));}
  function historyList(){const rows=historyRows();return rows.length?rows.slice(0,ui.history.limit).map(transactionRow).join('')+(rows.length>ui.history.limit?button('Cargar 50 movimientos más','load-more','','secondary full'):''):empty('Sin movimientos','Probá cambiar los filtros o registrar un movimiento.');}
  function history(){const f=ui.history;return header('Movimientos','',`${button(icon('template'),'go','templates','secondary','aria-label="Plantillas"')}<button class="icon-button" data-action="filters" aria-label="Filtrar movimientos">${icon('filter')}</button>`)+`<section class="content"><div><input id="history-search" type="search" placeholder="Buscar comercio o nota" aria-label="Buscar comercio o nota" value="${esc(f.search)}"></div><div class="tag-line">${['account','merchant','category','type','start','end'].filter(k=>f[k]).map(k=>`<span class="chip">${esc(k==='account'?aName(f[k]):k==='category'?cName(f[k]):k==='type'?typeLabels[f[k]]:f[k])}</span>`).join('')}${Object.values(f).some(v=>typeof v==='string'&&v)||f.report?'<button class="text-button" data-action="clear-filters">Limpiar filtros</button>':''}</div><div id="history-results">${historyList()}</div></section>`;}
  function accounts(){const rows=data.accounts.filter(a=>(ui.archived||!a.archived)&&(!ui.accountType||a.type===ui.accountType));return header('Cuentas','',`<button class="icon-button" data-action="account-new" aria-label="Agregar cuenta">${icon('plus')}</button>`)+`<section class="content"><div class="scroll-tabs">${[['','Todas'],['bank','Bancarias'],['cash','Efectivo'],['saving','Ahorro'],['credit','Crédito']].map(([id,name])=>`<button data-action="account-type" data-id="${id}" class="${ui.accountType===id?'active':''}">${name}</button>`).join('')}</div><label class="checkbox"><input type="checkbox" id="archived-accounts" ${ui.archived?'checked':''}>Mostrar también archivadas</label>${rows.length?rows.map(a=>`<div class="card"><button class="row" data-action="account" data-id="${a.id}"><span class="round-icon">${icon(a.type==='credit'?'card':a.type)}</span><span class="grow"><strong>${esc(a.name)}</strong><small>${accountLabels[a.type]}${a.archived?' · Archivada':''}</small></span><span class="money">${M.money(M.balance(data,a.id))}</span>${icon('arrow')}</button></div>`).join(''):empty('Sin cuentas para mostrar','Agregá una cuenta con el nombre que prefieras.',button('Agregar cuenta','account-new'))}</section>`;}
  function dataLine(label,value){return `<div class="data-line"><span>${label}</span><span>${value}</span></div>`;}
  function nextCreditDate(day){const date=`2026-10-${String(day).padStart(2,'0')}`;return date<M.TODAY?M.addMonths(date,1):date;}
  function accountDetail(){const a=M.account(data,view.id);if(!a)return header('Cuenta')+empty('Cuenta no disponible','Volvé a tus cuentas.');const bal=M.balance(data,a.id);return header(esc(a.name),accountLabels[a.type])+`<section class="content">${dataLine('Tipo',accountLabels[a.type])}${a.archived?'<span class="chip">Archivada</span>':''}<div class="hero"><span class="balance-label">${a.type==='credit'?'Deuda registrada':'Saldo registrado'}</span><div class="amount">${M.money(bal)}</div></div>${a.type==='credit'?`<div class="metric-grid"><div class="metric"><small>Límite</small><strong>${M.money(a.limit)}</strong></div><div class="metric"><small>Crédito disponible</small><strong>${M.money(a.limit-bal)}</strong></div></div>${dataLine('Próximo cierre',dateLabel(M.cardDates(a).closing))}${dataLine('Vencimiento estimado',dateLabel(M.cardDates(a).due))}${a.minimumPaymentMinor!=null?dataLine('Mínimo registrado manualmente',M.money(a.minimumPaymentMinor)):''}${!a.archived?button('Pagar esta tarjeta','pay',a.id,'primary full'):''}`:''}${a.type==='saving'?`<label class="switch-row"><div><strong>Incluir en dinero disponible</strong></div><input class="switch" type="checkbox" data-setting="saving" aria-label="Incluir en dinero disponible" data-id="${a.id}" ${a.available?'checked':''}></label>`:''}<div class="section-head"><h3>Administración</h3></div>${dataLine('Alias',esc(a.aliases.join(', ')||'Sin alias'))}<div class="actions">${button('Ver movimientos','account-history',a.id)}${button('Editar','account-edit',a.id)}</div><div class="actions">${!a.archived?button('Conciliar saldo','reconcile',a.id):''}${button(a.archived?'Reactivar':'Archivar','archive-account',a.id)}</div><div class="section-head"><h3>Movimientos de esta cuenta</h3></div>${M.movementRows(data).filter(t=>t.from===a.id||t.to===a.id).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(transactionRow).join('')||'<p class="muted">Sin movimientos todavía.</p>'}</section>`;}
  function detail(){const t=data.transactions.find(t=>t.id===view.id&&!t.deleted);if(!t)return header('Movimiento')+empty('Movimiento eliminado','Su efecto ya no se incluye en los saldos.',button('Volver','back'));if(view.index)return installmentDetail(t,view.index);return header(t.quotas>1?'Compra original':typeLabels[t.type])+`<section class="content"><div class="hero"><span class="eyebrow">${esc(t.merchant||typeLabels[t.type])}</span><div class="amount">${M.money(t.amount)}</div><p>${dateLabel(t.date)} · ${esc(t.source)}</p></div>${dataLine('Cuenta',esc(aName(t.from||t.to)))}${t.to&&t.from?dataLine('Destino',esc(aName(t.to))):''}${dataLine('Categoría',esc(t.splits?.length?t.splits.map(p=>cName(p.category)).join(' / '):cName(t.category)))}${dataLine('Canal',esc(t.channel))}${t.note?dataLine('Nota',esc(t.note)):''}${t.splits?.length?`<div class="card"><h3>División de categorías</h3>${t.splits.map(s=>dataLine(esc(cName(s.category)),M.money(s.amount))).join('')}</div>`:''}${t.quotas>1?`<div class="card"><h3>${t.quotas} cuotas</h3>${M.installmentSchedule(t).map((item,i)=>`<button class="row" data-action="installment-detail" data-id="${esc(t.id)}" data-index="${i+1}"><span class="grow"><strong>Cuota ${i+1}/${t.quotas}</strong><small>${dateLabel(item.date)}${item.date>M.TODAY?' · Prevista':''}</small></span><span class="money">${M.money(item.amount)}</span>${icon('arrow')}</button>`).join('')}</div>`:''}${t.purchase?dataLine('Compra original',`<button class="text-button" data-action="detail" data-id="${t.purchase}">Ver compra</button>`):''}${t.type==='expense'?dataLine('Disponible para devolver',M.money(M.refundable(data,t.id))):''}<div class="actions">${['expense','income','transfer'].includes(t.type)?button('Editar','edit-tx',t.id,'primary'):''}${!['adjustment','refund','payment'].includes(t.type)?button('Clonar','clone-tx',t.id):''}</div><div class="actions">${t.type==='expense'?button('Registrar devolución','refund',t.id):''}${button('Eliminar','delete-tx',t.id,'danger')}</div></section>`;}
  function installmentDetail(t,index){
    const item=t.type==='expense'&&t.quotas>1?M.installmentSchedule(t)[index-1]:null;
    if(!item)return header('Cuota')+empty('Cuota no disponible','El plan de la compra cambió.',button('Ver compra','detail',t.id));
    return header('Cuota '+index+'/'+t.quotas)+`<section class="content"><div class="hero"><span class="eyebrow">${esc(t.merchant||'Compra')}</span><div class="amount">${M.money(item.amount)}</div><p>${dateLabel(item.date)}${item.date>M.TODAY?' · Prevista':''}</p></div>${dataLine('Cuenta',esc(aName(t.from)))}${dataLine('Compra original',M.money(t.amount))}${dataLine('Fecha de compra',dateLabel(t.date))}${item.parts.map(p=>dataLine(esc(cName(p.category)),M.money(p.amount))).join('')}${button('Ver compra y todas sus cuotas','detail',t.id,'secondary full')}${button('Editar compra','edit-tx',t.id,'secondary full')}</section>`;
  }
  function periodControls(){return `<div class="period"><button class="icon-button" data-action="month" data-id="-1" aria-label="Mes anterior">${icon('back')}</button><button class="text-button" data-action="period">${ui.reportStart?dateLabel(ui.reportStart)+' – '+dateLabel(ui.reportEnd):monthLabel(ui.month)}</button><button class="icon-button" data-action="month" data-id="1" aria-label="Mes siguiente">${icon('arrow')}</button></div>`;}
  function analysis(){return header('Análisis','',ui.analysis==='reports'?`<button class="icon-button" data-action="report-history" aria-label="Ver movimientos del reporte" title="Ver movimientos">${icon('list')}</button>`:'')+`<section class="content"><div class="tabs">${['budgets','reports'].map((id,i)=>`<button data-action="analysis-tab" data-id="${id}" class="${ui.analysis===id?'active':''}">${i?'Reportes':'Presupuestos'}</button>`).join('')}</div>${ui.analysis==='budgets'?budgets():reports()}</section>`;}
  function budgets(){
    const month=ui.budgetMonth,rows=data.budgets.filter(b=>b.month===month);
    return `<div class="period"><button class="icon-button" data-action="budget-month" data-id="-1" aria-label="Mes de presupuesto anterior">${icon('back')}</button><button class="text-button" data-action="budget-period">${monthLabel(month)}</button><button class="icon-button" data-action="budget-month" data-id="1" aria-label="Mes de presupuesto siguiente">${icon('arrow')}</button></div><div class="budget-toolbar">${button('Mes actual','budget-today','','secondary')}${button(icon('plus')+' Crear','budget-new','','primary','aria-label="Crear presupuesto para '+monthLabel(M.month(M.TODAY))+'"')}</div><div class="budget-grid">${rows.map(b=>{
      const progress=M.budgetProgress(data,b),ratio=b.amount>0?progress.consumed/b.amount:0;
      // El porcentaje visual no modifica importes. El exceso no se oculta al completar el anillo.
      let percent=Math.round(ratio*100);if(ratio>1&&percent===100)percent=101;if(ratio<1&&ratio>=0&&percent===100)percent=99;
      return `<button class="budget-tile ${ratio>1?'over':''}" data-action="budget-detail" data-id="${esc(b.id)}" aria-label="${esc(b.name)}: ${percent}% consumido${ratio>1?', presupuesto excedido':''}. Ver detalle"><span class="budget-name">${esc(b.name)}</span><span class="budget-ring"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="ring-track" cx="60" cy="60" r="50"/><circle class="ring-value" cx="60" cy="60" r="50" pathLength="100" stroke-dasharray="${Math.max(0,Math.min(100,progress.paid/Math.max(b.amount,progress.consumed)*100))} 100"/><circle class="ring-pending" cx="60" cy="60" r="50" pathLength="100" stroke-dasharray="${Math.max(0,Math.min(progress.pending/Math.max(b.amount,progress.consumed)*100,100-Math.max(0,progress.paid/Math.max(b.amount,progress.consumed)*100)))} 100" stroke-dashoffset="${-Math.max(0,Math.min(100,progress.paid/Math.max(b.amount,progress.consumed)*100))}"/>${ratio>1?`<circle class="ring-excess" cx="60" cy="60" r="42" pathLength="100" stroke-dasharray="${Math.min(100,(ratio-1)*100)} 100"/>`:""}</svg><strong>${percent}<small>%</small></strong></span></button>`;
    }).join('')}</div><div class="payment-legend"><span><i></i>Pagado / contabilizado</span><span><i class="pending-key"></i>Pendiente</span></div>${rows.length?'':empty('No hay presupuestos para este mes','')}`;
  }
  function budgetDetail(id){
    const b=data.budgets.find(b=>b.id===id);if(!b)return;
    const progress=M.budgetProgress(data,b);
    openModal(b.name,`${dataLine('Mes',monthLabel(b.month))}${dataLine('Categoría',esc(b.category?cName(b.category):'Todas las categorías'))}${dataLine('Pagado / contabilizado',M.money(progress.paid))}${dataLine('Pendiente de pago',M.money(progress.pending))}${dataLine('Total comprometido',M.money(progress.consumed))}${dataLine('Objetivo',M.money(b.amount))}${dataLine(progress.remaining<0?'Exceso':'Restante',M.money(Math.abs(progress.remaining)))}${button('Ver movimientos','budget-history',b.id,'secondary full')}`);
  }
  function reportChange(current,previous){
    const delta=current-previous,arrow=delta>0?'↑':delta<0?'↓':'—';
    const rate=previous>0?Math.abs(delta)/previous*100:0;
    const value=previous>0?(rate>0&&rate<1?'<1%':Math.round(rate)+'%'):delta===0?'0%':previous===0&&current>0?'Nuevo':M.money(Math.abs(delta));
    const description=delta===0?'Sin cambios':(delta>0?'Subió ':'Bajó ')+M.money(Math.abs(delta));
    return `<span class="report-change" aria-label="${esc(description)} respecto al período anterior" title="Anterior: ${esc(M.money(previous))}">${arrow} ${esc(value)}</span>`;
  }
  function reportSummary(r,prev,prevStart){
    const comparison=ui.reportStart?'período anterior':new Date(prevStart+'T12:00:00').toLocaleDateString('es-PY',{month:'short'});
    const [start,end]=reportPeriod(),due=M.pendingAmount(data,start,end,{account:ui.reportAccount,category:ui.reportCategory});
    return `<div class="payment-report">${dataLine('Pendiente de pago',M.money(due))}${dataLine('Total comprometido',M.money(r.net+due))}</div><table class="report-summary"><thead><tr><th scope="col">Concepto</th><th scope="col">Importe <span class="comparison-context">· vs. ${comparison}</span></th></tr></thead><tbody><tr><th scope="row">Ingresos</th><td><span class="report-value">${M.money(r.income)}${reportChange(r.income,prev.income)}</span></td></tr><tr><th scope="row" title="Gastos menos devoluciones">Gastos</th><td><span class="report-value">${M.money(r.net)}${reportChange(r.net,prev.net)}</span></td></tr></tbody><tfoot><tr><th scope="row">Neto</th><td title="Ingresos menos gastos; no representa saldo de cuentas">${M.money(r.income-r.net)}</td></tr></tfoot></table><details class="inline report-breakdown"><summary>Detalle del gasto</summary>${dataLine('Gasto bruto',M.money(r.expenses))}${dataLine('Devoluciones',M.money(r.refunds))}${dataLine('Gasto neto',M.money(r.net))}</details>`;
  }
  function reportFilters(){
    openModal('Filtros del reporte',form('report-filters',`${selectField('Cuenta','account',accountOptions(ui.reportAccount,true,true))}${selectField('Categoría','category',categoryOptions(ui.reportCategory,'expense',true,true))}`,'Aplicar'));
  }
  function reportPeriod(){return [ui.reportStart||ui.month+'-01',ui.reportEnd||lastDay(ui.month)];}
  function reports(){const [start,end]=reportPeriod();const filters={account:ui.reportAccount,category:ui.reportCategory},r=M.report(data,start,end,'quotas',filters);const dayCount=Math.round((new Date(end)-new Date(start))/86400000)+1;let prevStart,prevEnd;if(!ui.reportStart){prevStart=M.addMonths(start,-1);prevEnd=lastDay(prevStart.slice(0,7));}else{prevEnd=new Date(new Date(start)-86400000).toISOString().slice(0,10);prevStart=new Date(new Date(start)-dayCount*86400000).toISOString().slice(0,10);}const prev=M.report(data,prevStart,prevEnd,'quotas',filters);const activeFilters=!!ui.reportAccount+!!ui.reportCategory;
    return `<div class="report-toolbar">${periodControls()}${button(icon('filter'),'report-filters','','secondary',`aria-label="Filtros del reporte${activeFilters?' ('+activeFilters+' activo'+(activeFilters===1?'':'s')+')':''}" title="Filtros"`)}</div><div class="report-view-row single-view"><select id="report-view" aria-label="Vista del reporte">${['Resumen','Evolución','Categorías','Comercios','Cuentas'].map(name=>`<option ${ui.reportView===name?'selected':''}>${name}</option>`).join('')}</select></div>${ui.reportView==='Resumen'?reportSummary(r,prev,prevStart):ui.reportView==='Evolución'?evolution(start,end):rankings(r,ui.reportView)}${ui.reportView==='Resumen'?'':``}`;}

  function evolution(start,end){const first=ui.reportStart?start.slice(0,7):M.addMonths(ui.month+'-01',-5).slice(0,7),last=ui.reportStart?end.slice(0,7):ui.month;const months=[];for(let m=first;m<=last&&months.length<120;m=M.addMonths(m+'-01',1).slice(0,7)){const r=M.report(data,m===start.slice(0,7)?start:m+'-01',m===end.slice(0,7)?end:lastDay(m),'quotas',{account:ui.reportAccount,category:ui.reportCategory});months.push({month:m,...r});}const max=Math.max(...months.map(r=>Math.max(Math.abs(r.net),r.income)),1);return `<div class="chart">${months.map(r=>`<div class="bar-group" title="${monthLabel(r.month)}: gasto neto ${M.money(r.net)}, ingreso ${M.money(r.income)}"><div class="bar ${r.net<0?'negative':''}" style="height:${Math.abs(r.net)/max*100}%"></div><div class="bar light" style="height:${r.income/max*100}%"></div><span class="bar-label">${r.month.slice(5)}</span></div>`).join('')}</div><div class="legend"><span><i></i>Gasto neto</span><span><i class="light"></i>Ingresos</span></div>${months.map(r=>`<button class="row" data-action="evolution-history" data-id="${r.month}"><span class="grow"><strong>${monthLabel(r.month)}</strong><small>Ingreso ${M.money(r.income)} · Devolución ${M.money(r.refunds)}</small></span><span class="money">${M.money(r.net)}</span>${icon('arrow')}</button>`).join('')}`;}
  function rankings(r,kind){const [start,end]=reportPeriod();let groups;if(kind==='Categorías'){groups=[...data.categories.filter(c=>c.kind!=='income').map(c=>({id:c.id,name:c.name,filter:'category'})),{id:'',name:'Sin categoría',filter:'category'}];}else if(kind==='Cuentas'){groups=data.accounts.map(a=>({id:a.id,name:a.name,filter:'account'}));}else{groups=[...new Set(r.rows.filter(row=>row.transaction.type!=='income').map(row=>row.transaction.merchant||''))].map(name=>({id:name,name:name||'Sin comercio',filter:'merchant'}));}if(kind==='Categorías'&&ui.reportCategory)groups=groups.filter(g=>g.id===ui.reportCategory);const results=groups.map(g=>{let exp=0,refund=0;for(const row of r.rows){const t=row.transaction;if(t.type==='income')continue;let amount=row.amount;if(g.filter==='category'){amount=M.parts(t).some(p=>p.category===g.id)?M.periodAmount(t,start,end,'quotas',g.id):0;if(!g.id){const unclassified=M.parts(t).filter(p=>!p.category);amount=unclassified.length?M.periodAmount(t,start,end,'quotas','',true):0;}}else if(g.filter==='account'&&t.from!==g.id&&t.to!==g.id)continue;else if(g.filter==='merchant'&&(t.merchant||'')!==g.id)continue;if(t.type==='expense')exp+=amount;else if(t.type==='refund')refund+=amount;}return {...g,exp,refund};}).filter(g=>g.exp||g.refund).sort((a,b)=>b.exp-a.exp);return results.length?results.map(g=>`<button class="row" data-action="ranking-history" data-id="${esc(g.id)}" data-filter="${g.filter}"><span class="grow"><strong>${esc(g.name)}</strong><small>Bruto ${M.money(g.exp)} · ${r.expenses?Math.round(g.exp/r.expenses*100):0}%<br>Devolución ${M.money(g.refund)}</small></span><span class="money">${M.money(g.exp-g.refund)}</span>${icon('arrow')}</button>`).join(''):empty('Sin datos para este desglose','Cambiá el período o los filtros.');}
  const menuRow=(name,subtitle,page,i)=>`<button class="row" data-action="go" data-id="${page}"><span class="round-icon">${icon(i)}</span><span class="grow"><strong>${name}</strong></span>${icon('arrow')}</button>`;
  function more(){return `<section class="content more-content" aria-label="Más" tabindex="-1"><div class="mini-title">ORGANIZACIÓN</div>${menuRow('Pagos pendientes','Cuotas, vencimientos y recordatorios','payments','calendar')}${menuRow('Plantillas','Gastos mensuales y anuales','templates','template')}${menuRow('Google Wallet','','wallet','card')}<div class="mini-title">TUS DATOS</div>${menuRow('Comercios, categorías y asociaciones','','catalog','store')}${menuRow('Backup cifrado','','backup','shield')}<div class="mini-title">SEGURIDAD E INFORMACIÓN</div>${menuRow('Bloqueo del dispositivo','','security','lock')}${menuRow('Información de la aplicación','','info','info')}${data.scenario==='developer'?`<div class="mini-title">DESARROLLO HABILITADO</div>${menuRow('Herramientas de desarrollo','','developer','test')}`:''}</section>`;}
  function inbox(){return header('Compras por revisar','',`<button class="icon-button" data-action="wallet-refresh" aria-label="Actualizar propuestas">${icon('refresh')}</button>`)+`<section class="content">${pending().map(p=>`<div class="card"><div class="row"><span class="round-icon">${icon('card')}</span><span class="grow"><strong>${esc(p.merchant)}</strong><small>${dateLabel(p.date)} · ${esc(p.alias)}</small></span><span class="money">${M.money(p.amount)}</span></div><p class="helper">${esc(p.reason)}</p><div class="tag-line"><span class="chip ${p.from?'':'warn'}">${p.from?'Cuenta reconocida':'Cuenta por asociar'}</span><span class="chip">${p.merchantState||(M.matchingMerchants(data,p.merchant).length===1?'Comercio reconocido':M.matchingMerchants(data,p.merchant).length>1?'Comercio ambiguo':'Comercio nuevo')}</span>${p.duplicate?'<span class="chip warn">Posible coincidencia</span>':''}</div><div class="actions">${button('Revisar','review',p.id,'primary')}${button('Descartar','discard',p.id)}</div></div>`).join('')||empty('Todo revisado','Las compras pendientes aparecerán acá. Hasta registrarlas no afectan tus saldos.')}</section>`;}
  function templates(){const scheduled=view.page==='scheduled';const rows=data.templates.filter(t=>!scheduled||t.schedule||t.paused||t.pending);return header('Plantillas','',`<button class="icon-button" data-action="template-new" aria-label="Crear plantilla">${icon('plus')}</button>`)+`<section class="content">${scheduled?`${button('Ver pagos pendientes','go','payments','','')}`:''}<div class="tabs">${button('Todas','template-view','templates',scheduled?'secondary':'primary active')}${button('Programadas','template-view','scheduled',scheduled?'primary active':'secondary')}</div>${rows.map(t=>`<div class="card"><h3>${esc(t.name)}</h3><p class="helper">${typeLabels[t.type]} · ${t.amount?M.money(t.amount):'Importe a completar'} · ${esc(aName(t.from||t.to))}</p>${t.schedule?`<span class="chip ${t.pending?'warn':''}">${t.paused?'Pausada':t.pending?'Pendiente':'Activa'} · ${t.frequency==='yearly'?'Anual':'Mensual'}</span><p class="helper">Próxima fecha: ${dateLabel(M.nextTemplateDate(data,t))}</p>`:'<span class="chip">Uso manual</span>'}${t.pending?`<p class="notice">${esc(t.pending)}</p>`:''}<div class="actions">${button('Usar','template-use',t.id,'primary')}${button('Editar','template-edit',t.id)}${button('Eliminar','template-delete',t.id)}</div>${t.schedule?`<div class="actions">${button(t.paused?'Reactivar':'Pausar','template-pause',t.id)}${t.pending?button('Omitir vencimiento','template-skip',t.id):''}</div>`:''}</div>`).join('')||empty(scheduled?'Sin programación':'Sin plantillas','Creá una plantilla con tus datos habituales.',button('Crear plantilla','template-new'))}</section>`;}
  function switchRow(title,help,key,value,disabled=false){return `<label class="switch-row"><div><strong>${title}</strong></div><input class="switch" type="checkbox" data-setting="${key}" aria-label="${esc(title)}" ${value?'checked':''} ${disabled?'disabled':''}></label>`;}
  function wallet(){return header('Google Wallet')+`<section class="content">${switchRow('Detectar compras','La captura se procesa al abrir o volver a la app.','wallet',data.settings.wallet)}${dataLine('Acceso Android',data.settings.permission?'Concedido (simulado)':'Sin permiso')}${button('Abrir ajustes de Android','permission','','secondary full')}${switchRow('Registrar compras reconocidas','Requiere detección y permiso activos, importe válido y cuenta activa/comercio únicos. Las compras nuevas o dudosas quedan por revisar.','auto',data.settings.auto)}${button('Simular compra reconocida','simulate-wallet','known','primary full')}${button('Simular comercio nuevo','simulate-wallet','new','secondary full')}${button('Simular comercio por alias','simulate-wallet','alias','secondary full')}${button('Simular actualización de la última captura','simulate-wallet','updated','secondary full')}${button('Ir a compras por revisar','go','inbox','secondary full')}</section>`;}
  function catalog(){const kind=ui.catalog;let rows=kind==='merchants'?data.merchants:kind==='categories'?data.categories:kind==='accountAliases'?data.accounts.flatMap(a=>a.aliases.map(alias=>({id:a.id,name:alias,target:a.name}))):data.merchants.flatMap(m=>m.aliases.map(alias=>({id:m.id,name:alias,target:m.name})));return header('Administrar datos','',`<button class="icon-button" data-action="catalog-add" aria-label="Agregar elemento">${icon('plus')}</button>`)+`<section class="content"><select id="catalog-kind" aria-label="Tipo de catálogo">${[['merchants','Comercios'],['categories','Categorías'],['accountAliases','Alias de cuentas'],['merchantAliases','Alias de comercios']].map(([id,name])=>`<option value="${id}" ${id===kind?'selected':''}>${name}</option>`).join('')}</select>${rows.map(r=>`<div class="card"><div class="row"><span class="grow"><strong>${esc(r.name)}</strong><small>${esc(r.target||r.kind||'Comercio')}${r.archived?' · Archivado':''}${kind==='accountAliases'&&data.accounts.filter(a=>!a.archived&&a.aliases.some(alias=>M.normalize(alias)===M.normalize(r.name))).length>1?' · Conflicto':''}</small></span>${kind==='merchants'?`<button class="text-button" data-action="merchant-history" data-id="${esc(r.name)}">Historial</button>`:''}</div><div class="actions">${button(r.target?'Reasignar':'Renombrar','catalog-edit',r.id,'secondary',`data-name="${esc(r.name)}"`)}${button(r.target?'Eliminar alias':r.archived?'Reactivar':'Archivar',r.target?'alias-delete':'catalog-archive',r.id,'secondary',`data-name="${esc(r.name)}"`)}</div></div>`).join('')||empty('Sin elementos','Agregá un nombre o una asociación.')}</section>`;}

  function backup(){return header('Backup cifrado')+`<section class="content"><div class="card">${icon('shield')}${button('Crear backup de demostración','backup-create','','primary full')}${button('Restaurar backup de demostración','backup-restore','','secondary full')}${previousRestore?button('Recuperar estado anterior a restaurar','backup-previous','','secondary full'):''}</div></section>`;}
  function security(){return header('Seguridad')+`<section class="content">${switchRow('Bloqueo del dispositivo','Biometría o credencial al abrir y volver a la app. Autorización simulada.','lock',data.settings.lock)}${button('Simular salir y volver','lock-now','','secondary full')}${dataLine('Cifrado local','Simulado')}</section>`;}
  function info(){return header('Información de la aplicación')+`<section class="content">${dataLine('Aplicación','Cabal')}${dataLine('Versión','Prototipo HTML')}${button('Licencias de terceros','licenses','','secondary full')}</section>`;}
  function developer(){if(data.scenario!=='developer')return header('Desarrollo')+empty('Herramientas desactivadas','Este escenario no permite acceder a funciones experimentales.');return header('Desarrollo','Solo escenario explícitamente habilitado')+`<section class="content">${menuRow('Simulador de notificaciones','Comercio, tarjeta e importe de prueba','simulator','test')}${switchRow('Alertas Sudameris vía Google Messages','Solo notificaciones. No lee la bandeja SMS.','sms',data.settings.sms)}${data.settings.sms?button('Simular una alerta SMS','sms-demo','','secondary full'):''}${switchRow('Modo diagnóstico','Retiene eventos ficticios para revisar.','diagnostic',data.settings.diagnostic)}${menuRow('Diagnóstico','Consultar, exportar y borrar','diagnostic','info')}${menuRow('Notificaciones existentes','Inspeccionar y crear propuesta','inspector','inbox')}</section>`;}
  function diagnostic(){if(data.scenario!=='developer')return developer();return header('Diagnóstico','Contenido ficticio de desarrollo')+`<section class="content">${data.diagnostic.map(d=>`<div class="card"><h3>${esc(d.title)}</h3><p class="muted">${esc(d.text)}</p></div>`).join('')||empty('Sin eventos','Activá diagnóstico y emití una notificación de prueba.')}<div class="actions">${button('Exportar sanitizado','diagnostic-export')}${button('Borrar eventos','clear-diagnostic','','danger')}</div></section>`;}
  function inspector(){if(data.scenario!=='developer')return developer();return header('Notificaciones existentes','Consulta simulada; no escribe gastos')+`<section class="content"><div class="card"><h3>Google Wallet · Ficticia</h3>${dataLine('Título','Compra en Mercado Verde')}${dataLine('Texto','185.000 PYG · •• 8820')}${dataLine('Comercio','Mercado Verde')}${dataLine('Cuenta sugerida','Crédito demo')}${button('Crear propuesta para revisar','inspect-create','','primary full')}${button('Repetir prueba tras eliminar','inspect-retest','','secondary full')}</div></section>`;}
  function onboarding(){return header('Configurar Cabal')+`<section class="content"><div class="step-dots">${[0,1,2].map(i=>`<span class="${i<=onboardingStep?'active':''}"></span>`).join('')}</div><div class="intro">${onboardingStep===0?`${icon('shield')}<h2>Datos locales</h2><div class="card"><h3>Guaraní paraguayo · PYG</h3></div>`:onboardingStep===1?`<h2>Cuentas</h2>${data.accounts.map(a=>`<div class="row"><span class="grow"><strong>${esc(a.name)}</strong><small>${accountLabels[a.type]}</small></span><button class="text-button" data-action="onboard-remove" data-id="${a.id}">Quitar</button></div>`).join('')}${button('Agregar cuenta','account-new','','secondary full')}`:`<h2>Bloqueo opcional</h2>${switchRow('Bloquear al abrir o volver','Autorización simulada en este prototipo.','lock',data.settings.lock)}`}</div><div class="actions">${onboardingStep?button('Atrás','onboard-back'):''}${button(onboardingStep===2?'Empezar':'Continuar','onboard-next','','primary')}</div></section>`;}

  function accountOptions(selected='',all=false,archived=false,exclude=''){return `<option value="">${all?'Todas las cuentas':'Elegí una cuenta'}</option>`+data.accounts.filter(a=>(archived||!a.archived||a.id===selected)&&a.id!==exclude).map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${esc(a.name)}${a.archived?' (archivada)':''}</option>`).join('');}
  function categoryOptions(selected='',type='expense',all=false,archived=false){return `<option value="">${all?'Todas las categorías':'Sin categoría'}</option>`+data.categories.filter(c=>(archived||!c.archived||c.id===selected)&&(type==='income'?c.kind!=='expense':c.kind!=='income')).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)}${c.archived?' (archivada)':''}</option>`).join('');}
  const field=(label,name,value='',type='text',attrs='')=>`<label class="field" for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(type==='text'&&attrs.includes('inputmode="numeric"')&&value!==''&&value!=null?M.money(M.parseMoney(value)).replace(' ₲',''):value)}" ${attrs}>`;
  const selectField=(label,name,options)=>`<label class="field" for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options}</select>`;
  const checkbox=(text,name,checked=false)=>`<label class="checkbox"><input type="checkbox" name="${name}" ${checked?'checked':''}>${text}</label>`;
  const form=(kind,body,submit='Guardar')=>`<form id="modal-form" data-kind="${kind}" novalidate>${body}<div id="form-error" class="error-box form-error" role="alert" tabindex="-1"></div><div class="actions">${button('Cancelar','close')}<button class="button" type="submit">${submit}</button></div></form>`;
  function openModal(title,body,payload={}){lastFocus=document.activeElement;modal={title,body,presentation:payload.presentation||'dialog',submitLabel:payload.submitLabel||'Guardar'};modalPayload={...payload,bookRevision:data.bookRevision||0};renderModal();const f=$('#modal-form');modalBaseline=f?new URLSearchParams(new FormData(f)).toString():'';}
  function overlayBounds(){const host=$('#app'),overlay=$('#overlay');if(!modal||!host)return;const r=host.getBoundingClientRect();overlay.style.setProperty('--app-left',r.left+'px');overlay.style.setProperty('--app-top',r.top+'px');overlay.style.setProperty('--app-width',r.width+'px');overlay.style.setProperty('--app-height',r.height+'px');}
  function renderModal(){const overlay=$('#overlay');$('.studio').inert=!!modal;$('.device').inert=!!modal;if(!modal){overlay.innerHTML='';return;}
    const screen=modal.presentation==='screen',sheet=modal.presentation==='sheet';
    overlay.innerHTML=`<div class="modal-backdrop ${screen?'screen-backdrop':sheet?'sheet-backdrop':''}"><section class="modal ${screen?'app-editor':sheet?'action-sheet':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title">${sheet?'<div class="sheet-handle" aria-hidden="true"></div>':''}<header class="modal-bar"><button class="modal-close" data-action="close" aria-label="${screen?'Volver':'Cerrar'}">${icon(screen?'back':'close')}</button><h2 id="modal-title">${esc(modal.title)}</h2>${screen?`<button class="text-button editor-save" type="submit" form="modal-form">${esc(modal.submitLabel)}</button>`:''}</header><div class="modal-body">${modal.body}</div></section></div>`;
    if(screen){overlay.querySelector('#modal-form>.actions')?.remove();overlay.querySelectorAll('label.field').forEach(label=>{if(label.parentElement.classList.contains('editor-field'))return;const control=label.nextElementSibling;if(!control||!['INPUT','SELECT','TEXTAREA'].includes(control.tagName))return;const row=document.createElement('div');row.className='editor-field';label.before(row);row.append(label,control);});}overlayBounds();overlay.querySelector('.modal-close')?.focus();}
  window.addEventListener('resize',overlayBounds);

  function close(force=false){const f=$('#modal-form');if(!force&&f&&modalBaseline!==new URLSearchParams(new FormData(f)).toString()){const previous={modal:{...modal,body:formSnapshot(f)},payload:modalPayload,baseline:modalBaseline};openModal('Descartar cambios',`<p>El formulario tiene cambios sin guardar.</p><div class="actions">${button('Seguir editando','dirty-keep')}${button('Descartar','dirty-discard','','danger')}</div>`,previous);return;}modal=null;modalPayload=null;renderModal();lastFocus?.focus();}
  function formSnapshot(f){const copy=f.cloneNode(true);const src=[...f.querySelectorAll('input,select,textarea')],dest=[...copy.querySelectorAll('input,select,textarea')];src.forEach((el,i)=>{const target=dest[i];if(el.tagName==='SELECT')[...target.options].forEach(o=>{o.toggleAttribute('selected',o.value===el.value);});else if(el.type==='checkbox')target.toggleAttribute('checked',el.checked);else if(el.tagName==='TEXTAREA')target.textContent=el.value;else target.setAttribute('value',el.value);});return copy.outerHTML;}
  function formError(error){const el=$('#form-error');if(el){el.textContent=error.message||String(error);el.focus({preventScroll:true});el.scrollIntoView({block:'nearest'});}else notify(error.message||String(error));}
  function confirmAction(title,text,action,id='',extra=''){openModal(title,`<p>${text}</p><div class="actions">${button('Cancelar','close')}${button('Confirmar',action,id,'primary',extra)}</div>`);}
  function composer(initial={},options={}) {
    if(!activeAccounts().length&&!options.template){openModal('Primero, una cuenta',`${button('Crear cuenta y continuar','account-resume','','primary full')}`,{resume:{initial,options}});return;}
    const draft={type:'expense',amount:null,date:M.TODAY,from:'',to:'',category:'',merchant:'',channel:'Otro',quotas:1,splits:[],note:'',...M.clone(initial)};
    const type=draft.type;const body=form(options.template?'template':'transaction',
      `${options.review?`<p class="notice">${esc(options.review.reason)}.</p>`:''}
      ${!options.template&&!options.edit&&!options.review&&type!=='payment'?'<button class="text-button" type="button" data-action="template-picker">Usar plantilla</button>':''}
      ${options.template?field('Nombre de la plantilla','name',draft.name||''):''}
      ${options.review||type==='payment'?`<span class="chip">${typeLabels[type]}</span><input type="hidden" name="type" value="${type}">`:`<input type="hidden" name="type" value="${type}">${options.edit?`<span class="chip">${typeLabels[type]}</span>`:`<div class="composer-types" role="group" aria-label="Tipo de movimiento">${['expense','income','transfer'].map(t=>button(typeLabels[t],'composer-type',t,t===type?'selected':'',`aria-pressed="${t===type}"`)).join('')}</div>`}`}
      ${field('Importe PYG','amount',draft.amount?M.money(draft.amount).replace(' ₲',''):'','text','class="amount-input" inputmode="numeric" autocomplete="off" placeholder="0"')}
      <div id="account-fields">${type!=='income'?selectField('Cuenta de origen','from',accountOptions(draft.from,false,!!options.edit)):''}${['income','transfer','payment'].includes(type)?selectField('Cuenta de destino','to',accountOptions(draft.to,false,!!options.edit,type==='income'?'':draft.from)).replace('<select ','<select '+(type==='payment'?'disabled ':' ')):''}</div>
      ${options.review?`<button type="button" class="text-button" data-action="inline-account">+ Crear cuenta para esta compra</button>`:''}
      <div id="category-fields" ${['transfer','payment'].includes(type)?'hidden':''}>${field(type==='income'?'Pagador':'Comercio','merchant',draft.merchant,'text','list="merchant-options" autocomplete="off"')}<datalist id="merchant-options">${data.merchants.filter(m=>!m.archived).map(m=>`<option value="${esc(m.name)}">`).join('')}</datalist>${selectField('Categoría','category',categoryOptions(draft.category,type,false,!!options.edit))}<button type="button" class="text-button" data-action="inline-category">+ Crear categoría</button>${!options.review?checkbox('Dividir entre categorías','split',draft.splits?.length>0):''}<div id="splits" ${draft.splits?.length?'':'hidden'}>${(draft.splits?.length?draft.splits:[{category:draft.category,amount:0},{category:'',amount:0}]).map(s=>splitRow(s,type)).join('')}<button type="button" class="text-button" data-action="add-split">+ Otra categoría</button><p id="split-total" class="helper" role="status" aria-live="polite"></p></div></div>
      <details class="inline" ${options.edit||draft.quotas>1?'open':''}><summary>Más detalles</summary>${field('Fecha','date',draft.date,'date',`max="${M.TODAY}"`)}${options.review?`<input type="hidden" name="channel" value="${options.review.sms?'Transferencia':'Google Wallet'}"><p class="helper">Canal: ${options.review.sms?'Transferencia':'Google Wallet'}</p>`:selectField('Canal','channel',M.channels(type,M.account(data,draft.from),M.account(data,draft.to)).map(c=>`<option ${c===draft.channel?'selected':''}>${c}</option>`).join(''))}${field('Nota','note',draft.note)}<div id="quota-fields" ${type==='expense'&&M.account(data,draft.from)?.type==='credit'?'':'hidden'}>${selectField('Cuotas','quotas',[1,2,3,4,6,10,12,18,24].map(n=>`<option value="${n}" ${n===draft.quotas?'selected':''}>${n===1?'Sin cuotas':n+' cuotas'}</option>`).join(''))}${!options.template?`<div id="first-installment-fields">${field('Primera cuota','firstInstallmentDate',draft.firstInstallmentDate||(draft.id?M.installmentStart(draft):draft.date),'date')}</div>`:''}</div></details>
      ${options.template?checkbox('Recordar importe','remember',draft.amount!==null)+checkbox('Crear pendientes de pago','schedule',draft.schedule)+`<div id="schedule-fields" ${draft.schedule?'':'hidden'}>${selectField('Frecuencia','frequency',`<option value="monthly" ${draft.frequency!=='yearly'?'selected':''}>Mensual</option><option value="yearly" ${draft.frequency==='yearly'?'selected':''}>Anual</option>`)}${field('Próxima fecha','next',draft.next||M.addMonths(M.TODAY,1),'date')}${reminderFields(draft.reminder||M.defaultReminder())}</div>`:!options.edit&&!options.review&&type!=='payment'?checkbox('Guardar también como plantilla','alsoTemplate')+`<div id="also-template-fields" hidden>${field('Nombre de la plantilla','templateName')} ${checkbox('Recordar importe en la plantilla','templateRemember',true)}${checkbox('Crear futuros pagos pendientes','templateSchedule')}<div id="combined-schedule-fields" hidden>${selectField('Frecuencia de la plantilla','templateFrequency','<option value="monthly">Mensual</option><option value="yearly">Anual</option>')}${field('Próxima fecha de la plantilla','templateNext',M.addMonths(draft.date,1),'date')}</div></div>`+checkbox('Guardar y crear otro','another'):''}`,
      options.template?'Guardar plantilla':options.review?'Registrar '+typeLabels[type].toLowerCase():options.edit?'Guardar cambios':type==='payment'?'Registrar pago':'Guardar movimiento');
    openModal(options.template?'Plantilla':options.review?'Revisar compra':options.edit?'Editar movimiento':type==='payment'?'Pagar tarjeta':'Nuevo movimiento',body,{draft,options,presentation:'screen',submitLabel:options.review?'Registrar':'Guardar'});updateComposer();modalBaseline=new URLSearchParams(new FormData($('#modal-form'))).toString();
  }
  function splitRow(s,type){return `<div class="split-row"><select name="splitCategory" aria-label="Categoría de división">${categoryOptions(s.category,type)}</select><input name="splitAmount" inputmode="numeric" value="${s.amount?M.money(s.amount).replace(' ₲',''):''}" placeholder="Importe" aria-label="Importe de división"><button type="button" data-action="remove-split" aria-label="Quitar división">${icon('close')}</button></div>`;}
  function updateComposer(){const f=$('#modal-form');if(!f||!['transaction','template'].includes(f.dataset.kind))return;const type=f.elements.type.value,from=f.elements.from?.value,to=f.elements.to?.value;const fromAccount=M.account(data,from);if(f.elements.channel&&f.elements.channel.tagName==='SELECT'){const value=f.elements.channel.value;const opts=M.channels(type,fromAccount,M.account(data,to));f.elements.channel.innerHTML=opts.map(c=>`<option ${c===value?'selected':''}>${c}</option>`).join('');}const credit=type==='expense'&&fromAccount?.type==='credit';$('#quota-fields').hidden=!credit;if(!credit&&f.elements.quotas)f.elements.quotas.value='1';const first=f.elements.firstInstallmentDate;if(first){const enabled=credit&&Number(f.elements.quotas.value)>1;$('#first-installment-fields').hidden=!enabled;first.disabled=!enabled;first.required=enabled;}if(f.elements.split){$('#splits').hidden=!f.elements.split.checked;f.elements.category.disabled=f.elements.split.checked;}if(f.elements.schedule){$('#schedule-fields').hidden=!f.elements.schedule.checked;if(f.elements.schedule.checked){f.elements.remember.checked=true;f.elements.remember.disabled=true;}else f.elements.remember.disabled=false;}if(f.elements.templateSchedule){const scheduled=f.elements.templateSchedule.checked;$('#combined-schedule-fields').hidden=!scheduled;f.elements.templateRemember.disabled=scheduled;if(scheduled)f.elements.templateRemember.checked=true;}updateSplitTotal();}
  function updateSplitTotal(){const f=$('#modal-form');if(!f?.elements.split?.checked)return;const sum=[...f.querySelectorAll('[name=splitAmount]')].reduce((s,input)=>s+(M.parseMoney(input.value)||0),0);$('#split-total').textContent=`Asignado ${M.money(sum)} · Falta ${M.money((M.parseMoney(f.elements.amount.value)||0)-sum)}`;}
  function readDraft(f){const payload=modalPayload;const v=new FormData(f),type=f.elements.type.value;return {...M.clone(payload.draft),type,amount:M.parseMoney(v.get('amount')),date:v.get('date')||M.TODAY,from:f.elements.from?.value||'',to:f.elements.to?.value||'',merchant:['transfer','payment'].includes(type)?'':String(v.get('merchant')||'').trim(),category:['transfer','payment'].includes(type)?'':f.elements.category.value,channel:f.elements.channel.value,note:v.get('note')||'',quotas:Number(f.elements.quotas?.value||1),firstInstallmentDate:Number(f.elements.quotas?.value||1)>1?(v.get('firstInstallmentDate')||payload.draft.firstInstallmentDate||undefined):undefined,splits:v.has('split')?v.getAll('splitCategory').map((category,i)=>({category,amount:M.parseMoney(v.getAll('splitAmount')[i])})):[]};}
  function collectTemplate(f,draft){const v=new FormData(f);const schedule=v.has('schedule');const remember=schedule||v.has('remember');const t={...draft,id:modalPayload.options.templateId||M.uid('template'),name:String(v.get('name')||'').trim(),amount:remember?draft.amount:null,schedule,frequency:v.get('frequency')||'monthly',next:v.get('next'),paused:!schedule&&!!modalPayload.draft.schedule,pending:null,reminder:readReminder(v)};if(!t.name)throw Error('Escribí un nombre para la plantilla.');if(schedule&&(t.type!=='expense'||t.quotas>1||!Number.isSafeInteger(t.amount)||t.amount<=0))throw Error('La programación requiere un gasto de importe fijo, sin cuotas.');if(schedule&&!t.next)throw Error('Elegí la próxima fecha.');if(remember)M.validate(data,t);if(!remember)t.splits=[];t.anchor=t.next===modalPayload.draft.next?modalPayload.draft.anchor||t.next:t.next;return t;}
  function accountForm(id='',inline=false){const parent=inline?(modalPayload.resume?{draft:{type:'expense',...modalPayload.resume.initial},options:modalPayload.resume.options}:{draft:readDraft($('#modal-form')),options:modalPayload.options}):null;const a=id?M.account(data,id):{name:'',type:'bank',initial:0,aliases:[],available:false,limit:0,closing:20,due:5};openModal(id?'Editar cuenta':'Nueva cuenta',form('account',`${field('Nombre','name',a.name)}${selectField('Tipo','accountType',Object.entries(accountLabels).map(([type,label])=>`<option value="${type}" ${a.type===type?'selected':''}>${label}</option>`).join('')).replace('<select ','<select '+(id?'disabled ':' '))}${!id?field('Saldo inicial / deuda inicial PYG','initial',a.initial?M.money(a.initial).replace(' ₲',''):'0','text','inputmode="numeric"'):''}${field('Alias (separados por coma)','aliases',a.aliases.join(', '))}<div id="savings-fields" ${a.type==='saving'?'':'hidden'}>${checkbox('Incluir en dinero disponible','available',a.available)}</div><div id="credit-fields" ${a.type==='credit'?'':'hidden'}>${field('Límite de crédito PYG','limit',a.limit?M.money(a.limit).replace(' ₲',''):'','text','inputmode="numeric"')}<div class="field-grid"><div>${field('Día de cierre','closing',a.closing||20,'number','min="1" max="31"')}</div><div>${field('Día de vencimiento','due',a.due||5,'number','min="1" max="31"')}</div></div></div>${id?'':''}`),{id,inline,parent});}
  function filtersForm(){const f=ui.history;openModal('Filtrar movimientos',form('filters',`${selectField('Cuenta','account',accountOptions(f.account,true,true))}${selectField('Comercio','merchant','<option value="">Todos los comercios</option>'+[...new Set(data.transactions.map(t=>t.merchant).filter(Boolean))].map(name=>`<option ${f.merchant===name?'selected':''}>${esc(name)}</option>`).join(''))}${selectField('Categoría','category',categoryOptions(f.category,'expense',true,true)+data.categories.filter(c=>c.kind==='income').map(c=>`<option value="${c.id}" ${c.id===f.category?'selected':''}>${esc(c.name)}</option>`).join(''))}${selectField('Tipo','type','<option value="">Todos los tipos</option>'+Object.entries(typeLabels).map(([id,name])=>`<option value="${id}" ${f.type===id?'selected':''}>${name}</option>`).join(''))}<div class="field-grid"><div>${field('Desde','start',f.start,'date')}</div><div>${field('Hasta','end',f.end,'date')}</div></div>`,'Aplicar'));}
  function catalogForm(id='',name=''){const kind=ui.catalog;const aliases=kind.endsWith('Aliases');const element=(kind==='merchants'?data.merchants:data.categories).find(r=>r.id===id);openModal(id?aliases?'Reasignar alias':'Renombrar':'Agregar elemento',form('catalog',`${field(aliases?'Alias':'Nombre','name',name,'text',id&&aliases?'readonly':'')}${aliases?selectField('Asociar a','target',kind==='accountAliases'?accountOptions(id):'<option value="">Elegí un comercio</option>'+data.merchants.filter(m=>!m.archived).map(m=>`<option value="${m.id}" ${id===m.id?'selected':''}>${esc(m.name)}</option>`).join('')):kind==='categories'&&!id?selectField('Tipo de categoría','kind',['expense','income','both'].map(k=>`<option value="${k}" ${k===element?.kind?'selected':''}>${{expense:'Gasto',income:'Ingreso',both:'Ambos'}[k]}</option>`).join('')):''}`),{id,name,kind});}
  function periodForm(){openModal('Elegir período',form('period',`${field('Mes','month',ui.month,'month')}${ui.analysis==='reports'?`<div class="field-grid"><div>${field('Desde','start',ui.reportStart,'date')}</div><div>${field('Hasta','end',ui.reportEnd,'date')}</div></div>`:''}`,'Aplicar'));}
  function reportHistory(filter=null,value=null,specificMonth=null){const [start,end]=reportPeriod();ui.history={search:'',account:ui.reportAccount,merchant:'',category:ui.reportCategory,type:'',start:specificMonth?specificMonth+'-01':start,end:specificMonth?lastDay(specificMonth):end,limit:50,report:true,mode:'quotas'};if(filter){ui.history[filter]=value;if(filter==='category'&&!value)ui.history.unclassified=true;if(filter==='merchant'&&!value)ui.history.withoutMerchant=true;}go('history');}

  function action(action,id,el){readLatest();try{switch(action){
    case 'movement-actions':movementActions();break;
    case 'composer-type':{const draft=readDraft($('#modal-form')),options=modalPayload.options;if(draft.type===id)break;draft.type=id;draft.from='';draft.to='';draft.category='';draft.splits=[];draft.quotas=1;composer(draft,options);}break;
    case 'plan-new':planForm();break;
    case 'payment-filter':ui.paymentFilter=id;render();break;
    case 'payment-detail':go('paymentDetail',{id});break;
    case 'payment-confirm':confirmPayment(id);break;
    case 'worth-info':openModal('Tu patrimonio financiero',`${dataLine('Dinero disponible',M.money(M.availableMoney(data)))}${dataLine('Deuda de compras y vencidos',M.money(M.obligationDebt(data)))}${dataLine('Patrimonio financiero',M.money(M.netWorth(data)))}${button('Entendido','close','','primary full')}`);break;
    case 'reminder-preview':{const o=obligations().find(o=>o.id===id);openModal('Recordatorio · Ejemplo',`<div class="notification-preview"><span>Cabal · Recordatorio</span><h3>¿Ya pagaste ${esc(o.name)}?</h3><p>${M.money(remaining(o))} · Vence ${dateLabel(o.due)}</p></div>${button('Revisar pago','reminder-open',id,'primary full')}${button('Cerrar aviso','close','','secondary full')}`);break;}
    case 'reminder-open':close(true);go('paymentDetail',{id});break;
    case 'reminder-edit':{const o=obligations().find(o=>o.id===id);openModal('Editar recordatorios',form('reminder',`${reminderFields(o.reminder||M.defaultReminder())}`),{id});break;}
    case 'obligation-edit':{const o=obligations().find(o=>o.id===id);openModal('Editar pendiente',form('obligation-edit',`${field('Importe previsto PYG','amount',o.amount,'text','inputmode="numeric"')}${field('Vencimiento','due',o.due,'date')}${checkbox('Aplicar también a los siguientes pendientes','following',!!o.templateId)}`),{id});break;}
    case 'obligation-cancel':confirmAction('Cancelar pendiente','Este vencimiento se cancela sin registrar un pago. Los demás vencimientos se conservan.','obligation-cancel-confirm',id);break;
    case 'obligation-cancel-confirm':{const o=obligations().find(o=>o.id===id);if(M.obligationPayments(data,id).length||o.carryIn||o.carryOut)throw Error('Este vencimiento tiene pagos o saldos trasladados. Conservá el historial y completá el saldo pendiente.');o.cancelled=true;close(true);render();notify('Pendiente cancelado.',()=>{o.cancelled=false;render();});break;}
    case 'scenario-confirm':close(true);reset(id);$('#scenario').value=id;notify('Escenario listo para explorar.');break;
    case 'dirty-keep':{const previous=modalPayload;modal=previous.modal;modalPayload=previous.payload;renderModal();modalBaseline=previous.baseline;break;}
    case 'dirty-discard':close(true);break;
    case 'nav':go(id,{},true);break;
    case 'go':if(id==='files')throw Error('Importación y exportación retiradas. Usá Backup para recuperar datos.');if(id==='simulator'){if(data.scenario!=='developer')throw Error('Herramientas desactivadas.');openModal('Notificación de prueba',form('simulator',`${field('Comercio','merchant','Mercado Verde')}${field('Identificador','alias','•• 8820')}${field('Importe mínimo PYG','min','45000','text','inputmode="numeric"')}${field('Importe máximo PYG','max','185000','text','inputmode="numeric"')}`,'Enviar prueba'));}else{if(['developer','diagnostic','inspector'].includes(id)&&data.scenario!=='developer')throw Error('Herramientas de desarrollo desactivadas.');go(id);}break;
    case 'back':back();break;case 'close':close();break;
    case 'new':composer({type:id});break;
    case 'detail':{const t=data.transactions.find(t=>t.id===id);if(t?.obligationId)go('paymentDetail',{id:t.obligationId});else go('detail',{id});break;}
    case 'installment-detail':go('detail',{id,index:Number(el.dataset.index)});break;
    case 'edit-tx':composer(data.transactions.find(t=>t.id===id),{edit:true});break;
    case 'clone-tx':{const t=M.clone(data.transactions.find(t=>t.id===id));delete t.id;delete t.revision;delete t.candidate;t.date=M.TODAY;delete t.firstInstallmentDate;delete t.firstPeriod;t.source='Manual';composer(t);break;}
    case 'delete-tx':{const t=data.transactions.find(t=>t.id===id);confirmAction(t?.quotas>1?'Eliminar compra y sus cuotas':'Eliminar movimiento','Su efecto se quitará de los saldos y del análisis. Podés deshacer esta acción.','delete-tx-confirm',id);break;}
    case 'delete-tx-confirm':M.deleteTransaction(data,id);close(true);back();notify('Movimiento eliminado.',()=>{M.restoreTransaction(data,id);render();});break;
    case 'undo':if(undoAction){const undo=undoAction;undoAction=null;undo();persist();$('#toast').className='';}break;
    case 'refund':{const t=data.transactions.find(t=>t.id===id);openModal('Registrar devolución',form('refund',`<p class="helper">${esc(t.merchant)} · Disponible: ${M.money(M.refundable(data,id))}</p>${field('Importe PYG','amount','','text','inputmode="numeric"')}${field('Fecha','date',M.TODAY,'date',`min="${t.date}" max="${M.TODAY}"`)}${field('Nota','note')}`,'Registrar devolución'),{id});break;}
    case 'filters':filtersForm();break;case 'clear-filters':ui.history={search:'',account:'',merchant:'',category:'',type:'',start:'',end:'',limit:50};render();break;case 'load-more':ui.history.limit+=50;render();break;
    case 'account':go('account',{id});break;
    case 'account-actions':{const a=M.account(data,id);openModal(a.name,`<p>${a.type==='credit'?'Deuda':'Saldo'}: ${M.money(M.balance(data,id))}</p>${a.type==='credit'?button('Pagar tarjeta','pay',id,'primary full'):''}${button('Ver movimientos','account-history',id,'secondary full')}${button('Administrar','account-open',id,'secondary full')}`);break;}
    case 'account-open':close(true);go('account',{id});break;
    case 'account-history':close(true);ui.history={search:'',account:id,merchant:'',category:'',type:'',start:'',end:'',limit:50};go('history');break;
    case 'account-type':ui.accountType=id;render();break;
    case 'account-resume':accountForm('',true);break;
    case 'account-new':accountForm();break;case 'account-edit':accountForm(id);break;case 'inline-account':accountForm('',true);break;
    case 'inline-category':openModal('Nueva categoría',form('inline-category',field('Nombre de la categoría','name')),{draft:readDraft($('#modal-form')),options:modalPayload.options});break;
    case 'archive-account':{const a=M.account(data,id);confirmAction(a.archived?'Reactivar cuenta':'Archivar cuenta',a.archived?'Volverá a estar disponible para nuevos movimientos.':'Se conserva su historial. Sale de cuentas activas y de la selección de nuevos movimientos.','archive-account-confirm',id);break;}
    case 'archive-account-confirm':{const a=M.account(data,id);a.archived=!a.archived;close(true);render();notify(a.archived?'Cuenta archivada.':'Cuenta reactivada.');break;}
    case 'reconcile':{const a=M.account(data,id);openModal('Conciliar '+a.name,form('reconcile',`<p class="helper">${a.type==='credit'?'Deuda':'Saldo'} registrado: ${M.money(M.balance(data,id))}</p>${field(a.type==='credit'?'Deuda real PYG':'Saldo real PYG','amount','','text','inputmode="numeric"')}${checkbox(a.type==='credit'?'Saldo a favor':'Saldo negativo','negative')}${field('Motivo del ajuste','note')}<p id="reconcile-diff" class="helper">Ingresá el saldo real para ver la diferencia.</p>`,'Guardar ajuste'),{id,expected:M.balance(data,id)});break;}
    case 'pay':close(true);composer({type:'payment',to:id,channel:'Transferencia'});break;
    case 'analysis-tab':ui.analysis=id;render();break;
    case 'report-filters':reportFilters();break;
    case 'template-view':view={page:id};render();break;
    case 'budget-detail':budgetDetail(id);break;
    case 'budget-history':{const b=data.budgets.find(b=>b.id===id);if(!b)break;close(true);ui.history={search:'',account:'',merchant:'',category:b.category||'',type:'',start:b.month+'-01',end:lastDay(b.month),limit:50,report:true,mode:'quotas'};go('history');break;}
    case 'budget-month':ui.budgetMonth=M.addMonths(ui.budgetMonth+'-01',Number(id)).slice(0,7);render();break;
    case 'budget-today':ui.budgetMonth=M.month(M.TODAY);render();break;
    case 'budget-period':openModal('Mes del presupuesto',form('budget-period',field('Mes','month',ui.budgetMonth,'month'),'Consultar'));break;
    case 'month':ui.month=M.addMonths(ui.month+'-01',Number(id)).slice(0,7);ui.reportStart='';ui.reportEnd='';render();break;
    case 'period':periodForm();break;case 'report-view':ui.reportView=id;render();break;
    case 'report-history':reportHistory();break;case 'evolution-history':reportHistory(null,null,id);break;case 'ranking-history':reportHistory(el.dataset.filter,id);break;
    case 'budget-new':openModal('Crear presupuesto',form('budget',`${field('Nombre','name','Mi mes')}${field('Objetivo PYG','amount','','text','inputmode="numeric"')}${selectField('Categoría','category',categoryOptions('','expense',true))}`,'Crear'));break;
    case 'template-new':composer({amount:null},{template:true});break;
    case 'template-picker':{const current=$('#modal-form').elements.type.value;const sorted=[...data.templates].sort((a,b)=>Number(b.type===current)-Number(a.type===current));openModal('Usar plantilla',`${sorted.map(t=>`<button class="row" data-action="template-use" data-id="${t.id}"><span class="grow"><strong>${esc(t.name)}</strong><small>${typeLabels[t.type]} · ${t.amount?M.money(t.amount):'Completar importe'}${t.schedule?' · '+(t.paused?'Pausada':t.pending?'Pendiente':dateLabel(M.nextTemplateDate(data,t))):''}</small></span>${icon('arrow')}</button>`).join('')||'<p class="muted">Todavía no hay plantillas.</p>'}${button('Administrar plantillas','template-manage','','secondary full')}`);break;}
    case 'template-manage':close(true);go('templates');break;
    case 'template-edit':{const t=M.clone(data.templates.find(t=>t.id===id));t.next=M.nextTemplateDate(data,t);composer(t,{template:true,templateId:id});break;}
    case 'template-use':{const t=M.clone(data.templates.find(t=>t.id===id));delete t.id;delete t.firstInstallmentDate;delete t.firstPeriod;t.date=M.TODAY;t.source='Manual';composer(t);break;}
    case 'template-delete':confirmAction('Eliminar plantilla','No modifica los movimientos ya registrados. Podés deshacer.','template-delete-confirm',id);break;
    case 'template-delete-confirm':{const t=M.clone(data.templates.find(t=>t.id===id));data.templates=data.templates.filter(t=>t.id!==id);close(true);render();notify('Plantilla eliminada.',()=>{data.templates.push(t);render();});break;}
    case 'template-pause':{const t=data.templates.find(t=>t.id===id);if(t.paused){composer(t,{template:true,templateId:id});}else{t.paused=true;render();notify('Programación pausada.');}break;}
    case 'template-skip':{const t=data.templates.find(t=>t.id===id);confirmAction('Omitir vencimiento',`No se registrará el gasto del ${dateLabel(M.nextTemplateDate(data,t))}. Se avanzará a la siguiente fecha.`, 'template-skip-confirm',id);break;}
    case 'template-skip-confirm':{const t=data.templates.find(t=>t.id===id);data.scheduleRuns.push(t.id+'@'+t.next);M.advance(t);t.pending=null;close(true);render();notify('Vencimiento omitido.');break;}
    case 'process-schedules':{const count=M.processSchedules(data);render();notify(`${count} pagos pendientes preparados. Los conflictos siguen pendientes.`);break;}
    case 'review':{const p=data.pending.find(p=>p.id===id);composer({...p,id:undefined,type:p.transactionType||'expense',channel:p.sms?'Transferencia':'Google Wallet',candidate:id},{review:p});break;}
    case 'discard':{const p=data.pending.find(p=>p.id===id);p.ignored=true;render();notify('Propuesta descartada. No modifica saldos.');break;}
    case 'wallet-refresh':notify('Cola ficticia actualizada. No se leen notificaciones reales.');break;
    case 'permission':permissionScene();break;
    case 'permission-grant':data.settings.permission=true;close(true);render();notify('Permiso simulado concedido. Volvé a activar la detección.');break;
    case 'permission-revoke':data.settings.permission=false;data.settings.wallet=false;close(true);render();notify('Permiso simulado revocado.');break;
    case 'simulate-wallet':simulateWallet(id);break;
    case 'catalog-add':catalogForm();break;case 'catalog-edit':catalogForm(id,el.dataset.name);break;
    case 'catalog-archive':{const list=ui.catalog==='merchants'?data.merchants:data.categories;const r=list.find(r=>r.id===id);r.archived=!r.archived;render();notify(r.archived?'Archivado. Historial conservado.':'Reactivado.');break;}
    case 'alias-delete':confirmAction('Eliminar alias',`La asociación «${esc(el.dataset.name)}» dejará de reconocerse. No cambia el historial.`, 'alias-delete-confirm',id,`data-name="${esc(el.dataset.name)}"`);break;
    case 'alias-delete-confirm':{const list=ui.catalog==='accountAliases'?data.accounts:data.merchants;const r=list.find(r=>r.id===id);r.aliases=r.aliases.filter(a=>a!==el.dataset.name);close(true);render();notify('Alias eliminado.');break;}
    case 'merchant-history':ui.history={search:'',account:'',merchant:id,category:'',type:'',start:'',end:'',limit:50};go('history');break;
    case 'backup-create':openModal('Contraseña del backup',form('backup-create',`${field('Contraseña ficticia (mínimo 8 caracteres)','password','','password','autocomplete="new-password"')}`,'Elegir destino'));break;
    case 'backup-destination':savedBackup=modalPayload;close(true);notify('Copia ficticia de esta sesión guardada. No se creó un archivo real.');break;
    case 'backup-restore':openModal('Elegir backup ficticio',`${savedBackup?button('Copia creada en esta sesión','backup-review','session','primary full'):''}${button('Backup válido de demostración','backup-review','valid','secondary full')}${button('Backup corrupto','backup-review','corrupt','secondary full')}${button('Esquema incompatible','backup-review','schema','secondary full')}`);break;
    case 'backup-review':{const book=id==='session'?savedBackup?.snapshot:M.seed(data.scenario==='first'?'daily':data.scenario);if(!book)throw Error('Creá primero una copia en esta sesión.');openModal('Revisar backup',form('backup-restore',`<p class="helper">Creado: ${id==='session'?dateLabel(M.TODAY):'5 oct 2026'} · ${id==='schema'?'Esquema no soportado':'Esquema de demostración'}<br>${book.accounts.length} cuentas · ${M.activeTransactions(book).length} movimientos ficticios</p><p class="notice">Se reemplazarán los datos de este escenario. Se simula una copia cifrada previa.</p>${field('Contraseña del backup','password','','password')}<p class="helper">${id==='session'?'':'Contraseña ficticia: <strong>cabal-demo</strong>'}</p>${checkbox('Confirmo reemplazar los datos ficticios','confirm')}`,'Restaurar'),{kind:id,book:M.clone(book)});break;}
    case 'backup-previous':confirmAction('Recuperar estado anterior','Se reemplazarán los datos ficticios por la copia previa conservada en memoria.','backup-previous-confirm');break;
    case 'backup-previous-confirm':if(!previousRestore)throw Error('No hay copia previa en esta sesión.');{const current=M.clone(data);data=M.restoreBook(current,previousRestore);undoAction=null;previousRestore=current;}close(true);render();notify('Estado anterior recuperado (solo demostración).');break;
    case 'lock-now':if(data.settings.lock){locked=true;render();}else notify('El bloqueo está desactivado.');break;
    case 'unlock':openModal('Bloqueo del dispositivo',`${button('Autenticación correcta','unlock-ok','','primary full')}${button('Cancelar o fallar','unlock-cancel','','secondary full')}`);break;
    case 'unlock-ok':locked=false;close(true);render();notify('Acceso concedido (simulación).');break;case 'unlock-cancel':close(true);notify('No se desbloqueó. Podés reintentar.');break;
    case 'lock-authorize':data.settings.lock=true;close(true);render();notify('Bloqueo activado (simulación).');break;
    case 'licenses':openModal('Licencias',`<p>El prototipo utiliza HTML, CSS y JavaScript propios, tipografías del sistema e íconos geométricos dibujados para esta demostración.</p><p>La app Flutter conserva su listado de licencias de terceros.</p>${button('Entendido','close','','primary full')}`);break;
    case 'diagnostic-export':if(data.scenario!=='developer')throw Error('Herramientas desactivadas.');openModal('Diagnóstico sanitizado',`${button('Cerrar','close')}`);break;
    case 'clear-diagnostic':if(data.scenario!=='developer')throw Error('Herramientas desactivadas.');data.diagnostic=[];render();notify('Eventos ficticios borrados.');break;
    case 'sms-demo':if(data.scenario!=='developer'||!data.settings.sms)throw Error('Activá SMS en el escenario de desarrollo.');openModal('Alerta SMS ficticia',`<p>Google Messages · Notificación experimental. No se lee ni envía un SMS real.</p>${button('Salario detectado','sms-candidate','income','primary full')}${button('Transferencia sin contraparte','sms-candidate','transfer','secondary full')}`);break;
    case 'sms-candidate':if(data.scenario!=='developer'||!data.settings.sms)throw Error('SMS experimental desactivado.');data.pending.push({id:M.uid('sms'),merchant:id==='income'?'Pagador demo':'',amount:id==='income'?4200000:100000,date:M.TODAY,from:id==='transfer'?'bank':'',to:id==='income'?'bank':'',transactionType:id,category:id==='income'?'salary':'',alias:'•• 4201',reason:id==='income'?'PRUEBA SMS · Ingreso por revisar':'PRUEBA SMS · Elegí la cuenta de destino',sms:true});close(true);go('inbox');notify('Propuesta SMS ficticia creada. Requiere revisión.');break;
    case 'inspect-create':if(data.scenario!=='developer')throw Error('Herramientas desactivadas.');if(!data.pending.some(p=>p.id==='inspect'))data.pending.push({id:'inspect',merchant:'Mercado Verde',amount:185000,date:M.TODAY,from:'credit',category:'food',alias:'•• 8820',reason:'PRUEBA · Inspección ficticia'});else notify('La propuesta ya existe.');go('inbox');break;
    case 'inspect-retest':if(data.scenario!=='developer')throw Error('Herramientas desactivadas.');if(data.transactions.some(t=>!t.deleted&&t.candidate==='inspect'))throw Error('Eliminá primero el movimiento activo de esta prueba.');{const p=data.pending.find(p=>p.id==='inspect');if(!p)throw Error('Primero creá una propuesta de esta prueba.');p.confirmed=false;p.ignored=false;go('inbox');notify('La misma propuesta se reabrió sin modificar saldos.');}break;
    case 'onboard-back':onboardingStep=Math.max(0,onboardingStep-1);render();break;case 'onboard-next':if(onboardingStep<2){onboardingStep++;render();}else{data.onboarding=true;go('home',{},true);notify('Cabal está listo para vos.');}break;
    case 'onboard-remove':data.accounts=data.accounts.filter(a=>a.id!==id);render();break;
    case 'add-split':$('#splits .text-button').insertAdjacentHTML('beforebegin',splitRow({category:'',amount:0},$('#modal-form').elements.type.value));updateSplitTotal();break;
    case 'remove-split':if($('#splits').querySelectorAll('.split-row').length<=2)throw Error('Una división necesita al menos dos partes.');el.closest('.split-row').remove();updateSplitTotal();break;
    default:throw Error('Recorrido no disponible.');
  }}catch(error){formError(error);}persist();}
  function permissionScene(){openModal('Acceso a notificaciones',`<p><strong>Ajustes de Android · Simulación</strong></p>${button('Conceder acceso ficticio','permission-grant','','primary full')}${data.settings.permission?button('Revocar acceso ficticio','permission-revoke','','secondary full'):''}${button('Cancelar','close','','secondary full')}`);}
  function simulateWallet(kind){
    const previous=data.pending.filter(p=>p.demoCapture).at(-1);
    if(kind==='updated'&&!previous)throw Error('Simulá primero una compra de Wallet.');
    const capture=kind==='updated'?{...previous,amount:previous.amount+1000}:{id:M.uid('candidate'),merchant:kind==='alias'?'MERCADO VERDE PY':kind==='known'?'Mercado Verde':'Tienda Nueva '+(pending().length+1),alias:'•• 8820',amount:78500,date:M.TODAY};
    const result=M.ingestWallet(data,capture);result.candidate.demoCapture=true;render();notify(result.status==='registered'?'Compra reconocida registrada automáticamente (ficticia).':result.status==='unchanged'?'Captura sin cambios. No se duplicó.':'Compra ficticia pendiente: '+result.candidate.reason);
  }

  function submit(f){readLatest();const values=new FormData(f),v=name=>values.get(name),kind=f.dataset.kind;const snapshot=M.clone(data);try{
    if((modalPayload.bookRevision||0)!==(data.bookRevision||0))throw Error('Se restauraron datos desde que abriste este formulario. Cancelá y volvé a abrirlo.');
    if(kind==='plan'){
      M.createPlan(data,{name:v('name'),amount:M.parseMoney(v('amount')),count:Number(v('count')),first:v('first'),from:v('from'),category:v('category'),reminder:readReminder(values)});close(true);go('payments');notify('Plan registrado.');
    }else if(kind==='obligation-payment'){
      if(remaining(obligations().find(o=>o.id===modalPayload.id))!==modalPayload.expectedRemaining)throw Error('Este pendiente cambió. Cerrá y volvé a abrir el pago.');
      M.payObligation(data,modalPayload.id,{amount:M.parseMoney(v('amount')),date:v('date'),from:v('from'),carry:values.has('carry'),finalAmount:values.has('finalAmount')});close(true);render();notify('Pago confirmado. Saldo y pendientes actualizados.');
    }else if(kind==='reminder'){
      M.saveReminder(data,modalPayload.id,readReminder(values));
      close(true);render();notify('Recordatorios actualizados.');
    }else if(kind==='obligation-edit'){
      M.editObligation(data,modalPayload.id,{amount:M.parseMoney(v('amount')),due:v('due'),following:values.has('following')});
      close(true);render();notify('Pendientes actualizados. Pagos anteriores conservados.');
    }else if(kind==='inline-category'){const name=String(v('name')||'').trim();if(!name)throw Error('Ingresá el nombre de la categoría.');const parent=modalPayload;const c={id:M.uid('category'),name,kind:parent.draft.type==='income'?'income':'expense'};data.categories.push(c);parent.draft.category=c.id;close(true);composer(parent.draft,parent.options);notify('Categoría creada en la demostración.');
    }else if(kind==='transaction') {
      const {options}=modalPayload;const draft=readDraft(f);if(options.review){draft.source=options.review.sms?'SMS experimental':options.review.test?'PRUEBA de desarrollo':'Google Wallet';draft.candidate=options.review.id;draft.channel=options.review.sms?'Transferencia':'Google Wallet';}
      let template;if(values.has('alsoTemplate')){const scheduled=values.has('templateSchedule');template={...M.clone(draft),id:M.uid('template'),name:String(v('templateName')||'').trim(),amount:scheduled||values.has('templateRemember')?draft.amount:null,schedule:scheduled,frequency:v('templateFrequency')||'monthly',next:v('templateNext'),anchor:v('templateNext'),paused:false,pending:null};if(template.amount===null)template.splits=[];}
      const t=M.saveWithTemplate(data,draft,template);if(template?.schedule)M.processSchedules(data);
      if(options.review){const p=data.pending.find(p=>p.id===options.review.id);p.confirmed=true;const a=M.account(data,draft.from||draft.to);if(a&&p.alias&&!a.aliases.some(alias=>M.normalize(alias)===M.normalize(p.alias)))a.aliases.push(p.alias);const merchant=data.merchants.find(m=>!m.archived&&M.normalize(m.name)===M.normalize(draft.merchant));if(merchant&&p.merchant&&M.normalize(p.merchant)!==M.normalize(merchant.name)&&!merchant.aliases.some(a=>M.normalize(a)===M.normalize(p.merchant))){if(data.merchants.some(m=>m.id!==merchant.id&&m.aliases.some(a=>M.normalize(a)===M.normalize(p.merchant))))throw Error('Este alias ya pertenece a otro comercio. Reasignalo explícitamente en Catálogos.');merchant.aliases.push(p.merchant);}}
      const another=values.has('another');close(true);render();notify(options.edit?'Movimiento actualizado.':options.review?'Compra registrada. Asociaciones recordadas.':'Movimiento guardado.');if(another)composer({type:t.type,from:t.from,to:t.to});
    }else if(kind==='template') {
      const draft=readDraft(f),t=collectTemplate(f,draft);M.saveTemplate(data,t,modalPayload.draft.next);close(true);render();notify('Plantilla guardada. Los pagos anteriores se conservan.');
    }else if(kind==='account') {
      const {id,inline,parent}=modalPayload;const old=id?M.account(data,id):null;const type=f.elements.accountType.value;const name=String(v('name')||'').trim();if(!name)throw Error('Ingresá el nombre de la cuenta.');const initial=old?old.initial:M.parseMoney(v('initial'));if(!Number.isSafeInteger(initial)||initial<0)throw Error('El saldo inicial debe ser un importe entero positivo o cero.');const aliases=String(v('aliases')||'').split(',').map(a=>a.trim()).filter(Boolean);const account={...old,id:id||M.uid('account'),name,type,initial,aliases:[...new Set(aliases)],available:type==='saving'?values.has('available'):type!=='credit'};if(type==='credit'){account.limit=M.parseMoney(v('limit'));account.closing=Number(v('closing'));account.due=Number(v('due'));if(!Number.isSafeInteger(account.limit)||account.limit<=0||![account.closing,account.due].every(day=>Number.isInteger(day)&&day>=1&&day<=31))throw Error('Completá un límite válido y días entre 1 y 31.');}
      if(old)data.accounts[data.accounts.indexOf(old)]=account;else data.accounts.push(account);close(true);render();notify('Cuenta guardada.');if(inline){if(parent.draft.type==='income')parent.draft.to=account.id;else parent.draft.from=account.id;composer(parent.draft,parent.options);}
    }else if(kind==='refund'){const t=M.refund(data,modalPayload.id,M.parseMoney(v('amount')),v('date'),v('note'));close(true);render();notify('Devolución registrada: '+M.money(t.amount));
    }else if(kind==='reconcile'){const {id,expected}=modalPayload;if(M.balance(data,id)!==expected)throw Error('El saldo cambió. Volvé a abrir la conciliación.');const raw=M.parseMoney(v('amount'));if(!Number.isSafeInteger(raw)||raw<0)throw Error('Ingresá un saldo real válido.');const target=values.has('negative')?-raw:raw,difference=target-expected;if(!difference)throw Error('El saldo ya coincide; no hace falta ajuste.');data.transactions.push({id:M.uid('adjustment'),type:'adjustment',amount:difference,date:M.TODAY,from:id,to:'',merchant:'Conciliación',category:'',splits:[],quotas:1,source:'Manual',channel:'Otro',note:v('note')||''});close(true);render();notify('Ajuste registrado. No consume presupuesto.');
    }else if(kind==='filters'){if(v('start')&&v('end')&&v('start')>v('end'))throw Error('El período termina antes de empezar.');for(const key of ['account','merchant','category','type','start','end'])ui.history[key]=v(key)||'';ui.history.limit=50;close(true);render();
    }else if(kind==='report-filters'){ui.reportAccount=v('account')||'';ui.reportCategory=v('category')||'';close(true);render();
    }else if(kind==='period'){if(!v('month'))throw Error('Elegí un mes.');const start=v('start')||'',end=v('end')||'';if((start&&!end)||(!start&&end)||(start&&start>end))throw Error('Completá ambas fechas en orden.');if(start&&Math.round((new Date(end)-new Date(start))/86400000)>3650)throw Error('Para esta demo elegí un período de hasta diez años.');ui.month=v('month');ui.reportStart=start;ui.reportEnd=end;close(true);render();
    }else if(kind==='budget-period'){if(!/^\d{4}-\d{2}$/.test(v('month')||'')||!M.validDate(v('month')+'-01'))throw Error('Elegí un mes válido.');ui.budgetMonth=v('month');close(true);render();
    }else if(kind==='budget'){M.createBudget(data,{name:String(v('name')||'').trim(),amount:M.parseMoney(v('amount')),category:v('category')||''});close(true);render();notify('Presupuesto creado para '+monthLabel(M.month(M.TODAY))+'.');
    }else if(kind==='catalog') {
      const {id,kind:catalogKind,name:oldName}=modalPayload;const name=String(v('name')||'').trim();if(!name)throw Error('Ingresá un nombre o alias.');if(catalogKind.endsWith('Aliases')){const list=catalogKind==='accountAliases'?data.accounts:data.merchants;const target=list.find(t=>t.id===v('target')&&!t.archived);if(!target)throw Error('Elegí un destino activo.');const existing=list.filter(t=>t.aliases.some(alias=>M.normalize(alias)===M.normalize(name)));if(!id&&existing.some(t=>t.id!==target.id))throw Error('Ese alias ya existe en otro elemento. Usá Reasignar explícitamente.');if(id){const original=list.find(t=>t.id===id);original.aliases=original.aliases.filter(a=>a!==oldName);}if(!target.aliases.some(a=>M.normalize(a)===M.normalize(name)))target.aliases.push(name);}else {const list=catalogKind==='merchants'?data.merchants:data.categories;if(list.some(r=>r.id!==id&&M.normalize(r.name)===M.normalize(name)))throw Error('Ya hay un elemento con ese nombre.');if(id)list.find(r=>r.id===id).name=name;else list.push({id:M.uid(catalogKind),name,...(catalogKind==='merchants'?{aliases:[],category:''}:{kind:v('kind')})});}close(true);render();notify('Catálogo actualizado. El historial se conserva.');

    }else if(kind==='backup-create'){if(String(v('password')||'').length<8)throw Error('La contraseña requiere al menos 8 caracteres.');openModal('Elegir destino',`${button('Guardar backup ficticio','backup-destination','','primary full')}`,{snapshot:M.clone(data),password:String(v('password'))});
    }else if(kind==='backup-restore'){if(!values.has('confirm'))throw Error('Confirmá el reemplazo de los datos ficticios.');if(v('password')!==(modalPayload.kind==='session'?savedBackup?.password:'cabal-demo'))throw Error('Contraseña incorrecta. Los datos actuales se conservan.');if(modalPayload.kind==='corrupt')throw Error('Backup corrupto. No se modificó ningún dato.');if(modalPayload.kind==='schema')throw Error('Esquema incompatible. No se modificó ningún dato.');previousRestore=M.clone(data);data=M.restoreBook(data,modalPayload.book);undoAction=null;data.onboarding=true;close(true);view={page:'home'};stack=[];render();notify('Backup ficticio validado y restaurado. Copia previa conservada en memoria.');
    }else if(kind==='simulator'){if(data.scenario!=='developer')throw Error('Herramientas desactivadas.');const min=M.parseMoney(v('min')),max=M.parseMoney(v('max'));if(![min,max].every(Number.isSafeInteger)||min<=0||max<min)throw Error('Definí un rango de importes válido.');const name=String(v('merchant')||'').trim();if(!name)throw Error('Ingresá un comercio.');const alias=String(v('alias')||'').trim();const matches=activeAccounts().filter(a=>a.aliases.some(a=>M.normalize(a)===M.normalize(alias)));const p={id:M.uid('test'),merchant:name,amount:Math.floor(min+Math.random()*(max-min+1)),date:M.TODAY,from:matches.length===1?matches[0].id:'',alias,category:'',reason:'PRUEBA · Notificación ficticia',test:true};data.pending.push(p);if(data.settings.diagnostic)data.diagnostic.push({title:'PRUEBA',text:name+' · '+M.money(p.amount)+' · '+alias});close(true);go('inbox');notify('Notificación PRUEBA emitida y capturada (simulación).');
    }
    persist();
  }catch(error){data=snapshot;formError(error);}}

  document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible')return;readLatest();const count=M.processSchedules(data);if(count){persist();if(!modal)render();notify(count+' pagos pendientes preparados al volver a esta demostración.');}});
  window.addEventListener('storage',event=>{if(event.key!=='cabal-prototype-v1'||!event.newValue)return;try{const next=JSON.parse(event.newValue);if(!next?.transactions||!next?.categories||event.newValue===JSON.stringify(data))return;data=next;if(modal){if(modalPayload?.options?.edit)formError('Hay cambios en otra pestaña. Al guardar se comprobará la versión del movimiento.');}else{receivingStorage=true;try{render();}finally{receivingStorage=false;}}}catch{}});
  document.addEventListener('click',event=>{if(modal?.presentation==='sheet'&&event.target.classList.contains('sheet-backdrop')){close();return;}const fab=$('.home-fab[open]');if(fab&&!event.target.closest('.home-fab'))fab.open=false;const el=event.target.closest('[data-action]');if(el){event.preventDefault();action(el.dataset.action,el.dataset.id||'',el);}});
  document.addEventListener('submit',event=>{if(event.target.id==='modal-form'){event.preventDefault();submit(event.target);}});
  document.addEventListener('change',event=>{const el=event.target;try{
    if(el.id==='scenario'){const scenario=el.value;el.value=data.scenario;confirmAction('Cambiar escenario','Se reinician los datos ficticios para explorar el escenario elegido.','scenario-confirm',scenario);return;}
    if(el.id==='archived-accounts'){ui.archived=el.checked;render();}
    if(el.id==='catalog-kind'){ui.catalog=el.value;render();}
    if(el.id==='report-view'){ui.reportView=el.value;render();}
    if(el.id==='report-account'){ui.reportAccount=el.value;render();}
    if(el.id==='report-category'){ui.reportCategory=el.value;render();}
    if(el.dataset.setting){const key=el.dataset.setting;if(key==='saving')M.account(data,el.dataset.id).available=el.checked;else if(['sms','diagnostic'].includes(key)){if(data.scenario!=='developer')throw Error('Herramientas de desarrollo desactivadas.');data.settings[key]=el.checked;}else if(key==='wallet'&&el.checked&&!data.settings.permission){el.checked=false;permissionScene();return;}else if(key==='lock'&&el.checked){el.checked=false;openModal('Activar bloqueo',`${button('Autorizar con biometría o credencial','lock-authorize','','primary full')}${button('Cancelar','close','','secondary full')}`);return;}else data.settings[key]=el.checked;render();}
    const f=el.closest('#modal-form');if(f){
      if(f.dataset.kind==='account'&&el.name==='accountType'){$('#credit-fields').hidden=el.value!=='credit';$('#savings-fields').hidden=el.value!=='saving';}
      if(['transaction','template'].includes(f.dataset.kind)){
        if(el.name==='type'){const draft=readDraft(f),options=modalPayload.options;draft.from='';draft.to='';draft.category='';draft.splits=[];draft.quotas=1;composer(draft,options);return;}
        if(el.name==='date'&&f.elements.firstInstallmentDate){const first=f.elements.firstInstallmentDate;if(!first.value||first.value===first.defaultValue)first.value=el.value;}
        if(el.name==='merchant'){const matches=M.matchingMerchants(data,el.value),m=matches.length===1?matches[0]:null;if(m&&!f.elements.split?.checked){const c=data.categories.find(c=>c.id===m.category&&!c.archived);f.elements.category.value=c?.id||'';el.value=m.name;}}
        if(el.name==='alsoTemplate')$('#also-template-fields').hidden=!el.checked;
        if(['templateFrequency','date'].includes(el.name)&&f.elements.templateNext){f.elements.templateNext.value=M.addMonths(f.elements.date.value||M.TODAY,f.elements.templateFrequency.value==='yearly'?12:1);}
        if(el.name==='frequency'&&f.elements.next&&!modalPayload.options.templateId)f.elements.next.value=M.addMonths(M.TODAY,el.value==='yearly'?12:1);
        if(el.name==='from'&&f.elements.to&&f.elements.type.value==='transfer'){const current=f.elements.to.value;f.elements.to.innerHTML=accountOptions(current,false,!!modalPayload.options.edit,el.value);}
        updateComposer();
      }
    }persist();
  }catch(error){notify(error.message);}});
  document.addEventListener('input',event=>{const el=event.target;if(el.id==='history-search'){ui.history.search=el.value;ui.history.limit=50;$('#history-results').innerHTML=historyList();}if(['amount','splitAmount','min','max','limit','initial'].includes(el.name)&&el.type!=='number'){const value=el.value;const pos=el.selectionStart;const count=value.slice(0,pos).replace(/\D/g,'').length;const digits=value.replace(/\D/g,'');el.value=digits?new Intl.NumberFormat('es-PY').format(Number(digits)):'';let cursor=0,seen=0;while(cursor<el.value.length&&seen<count){if(/\d/.test(el.value[cursor]))seen++;cursor++;}try{el.setSelectionRange(cursor,cursor);}catch{}}updateSplitTotal();const f=el.closest('#modal-form');if(f?.dataset.kind==='reconcile'){const amount=M.parseMoney(f.elements.amount.value)||0;$('#reconcile-diff').textContent='Ajuste: '+M.money((f.elements.negative.checked?-amount:amount)-modalPayload.expected);}});
  document.addEventListener('keydown',event=>{if(!modal){const fab=$('.home-fab[open]');if(fab&&event.key==='Escape'){event.preventDefault();fab.open=false;fab.querySelector('summary').focus();}return;}if(event.key==='Escape'){event.preventDefault();close();}if(event.key==='Tab'){const nodes=[...$('#overlay').querySelectorAll('button,input,select,textarea,summary,a')].filter(el=>!el.disabled&&el.offsetParent!==null);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
  $('#reset').addEventListener('click',()=>confirmAction('Reiniciar escenario','Se descartan los cambios de demostración y se vuelve a los datos de ejemplo.','scenario-confirm',data.scenario));
  load();const requested=new URLSearchParams(location.search).get('scenario');if(['daily','first','credit','wallet','scheduled','analysis','files','developer','payments'].includes(requested))reset(requested);else render();const startupCount=M.processSchedules(data);render();if(startupCount){notify(startupCount+' pagos pendientes preparados al abrir esta demostración.');}
})();
